#!/usr/bin/env python3
"""IdentityShield 30-day memory installer.

Usage (from the project root, the folder that contains app/ and static/):
    python install_memory30.py          install / update
    python install_memory30.py --check  verify installed files match this installer

What it does:
  1. Backs up any file it will overwrite to .mem30_backup/<timestamp>/
  2. Writes app/memory30/ (engine, store, normalizer, synthetic data, API), static/memory.html,
     static/js/memory30.js and tests/test_memory30.py
  3. Adds the /api/memory router to app/main.py (before the static mount)
  4. Adds data/memory30.sqlite* and data/synth/ to .gitignore
  5. Runs a self-test: 30 days of synthetic data, 3 hidden slow attacks must be found with 0 false positives
"""
import argparse
import json
import py_compile
import shutil
import sys
import tempfile
import time
from pathlib import Path

FILES = json.loads('{"app/memory30/__init__.py": "\\"\\"\\"IdentityShield 30-day identity memory.\\n\\nSelf-contained add-on: reads Okta System Log and AWS CloudTrail JSON, keeps a tiered 30-day memory per identity\\nin SQLite (7 days raw events, permanent evidence, 30 days of compact daily summaries and attack-stage hits),\\nlinks slow multi-day attack chains, and exposes the results under /api/memory.\\n\\"\\"\\"\\n__all__ = [\\"engine\\", \\"store\\", \\"normalize\\", \\"catalog\\", \\"synth\\", \\"config\\"]\\n", "app/memory30/__main__.py": "\\"\\"\\"CLI: python -m app.memory30 <command>\\n\\n  synth   --days 30 --identities 200 --seed 42 [--out data/synth] [--ingest]   generate synthetic 30-day data\\n  ingest  [paths ...]                                                          ingest JSON files or folders\\n  prune   [--vacuum]                                                           apply 7-day / 30-day retention\\n  stats                                                                        storage and memory statistics\\n  report  [--labels data/synth/labels.json]                                    findings vs synthetic labels\\n  reset   --yes                                                                empty the memory database\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport json\\nimport sys\\nfrom pathlib import Path\\n\\nfrom . import config, synth\\nfrom .engine import MemoryEngine\\n\\n\\ndef _print(obj) -> None:\\n    print(json.dumps(obj, indent=2, default=str))\\n\\n\\ndef main(argv: list[str] | None = None) -> int:\\n    ap = argparse.ArgumentParser(prog=\\"python -m app.memory30\\")\\n    ap.add_argument(\\"--db\\", default=None, help=\\"SQLite path (default data/memory30.sqlite)\\")\\n    sub = ap.add_subparsers(dest=\\"cmd\\", required=True)\\n    s = sub.add_parser(\\"synth\\")\\n    s.add_argument(\\"--days\\", type=int, default=30)\\n    s.add_argument(\\"--identities\\", type=int, default=200)\\n    s.add_argument(\\"--seed\\", type=int, default=42)\\n    s.add_argument(\\"--out\\", default=str(config.SYNTH_DIR))\\n    s.add_argument(\\"--ingest\\", action=\\"store_true\\")\\n    i = sub.add_parser(\\"ingest\\")\\n    i.add_argument(\\"paths\\", nargs=\\"*\\")\\n    p = sub.add_parser(\\"prune\\")\\n    p.add_argument(\\"--vacuum\\", action=\\"store_true\\")\\n    sub.add_parser(\\"stats\\")\\n    r = sub.add_parser(\\"report\\")\\n    r.add_argument(\\"--labels\\", default=str(config.SYNTH_DIR / \\"labels.json\\"))\\n    x = sub.add_parser(\\"reset\\")\\n    x.add_argument(\\"--yes\\", action=\\"store_true\\")\\n    args = ap.parse_args(argv)\\n\\n    if args.cmd == \\"synth\\":\\n        info = synth.write(args.out, args.days, args.identities, args.seed)\\n        _print(info)\\n        if args.ingest:\\n            eng = MemoryEngine(args.db)\\n            _print(eng.ingest_paths([Path(args.out) / \\"okta\\", Path(args.out) / \\"cloudtrail\\"]))\\n            labels = json.loads((Path(args.out) / \\"labels.json\\").read_text(encoding=\\"utf-8\\"))\\n            _print(synth.report(eng, labels))\\n        return 0\\n    eng = MemoryEngine(args.db)\\n    if args.cmd == \\"ingest\\":\\n        _print(eng.ingest_paths(args.paths or None))\\n    elif args.cmd == \\"prune\\":\\n        _print(eng.prune(vacuum=args.vacuum))\\n    elif args.cmd == \\"stats\\":\\n        _print(eng.stats())\\n    elif args.cmd == \\"report\\":\\n        lp = Path(args.labels)\\n        if not lp.exists():\\n            print(f\\"labels file not found: {lp}\\", file=sys.stderr)\\n            return 2\\n        _print(synth.report(eng, json.loads(lp.read_text(encoding=\\"utf-8\\"))))\\n    elif args.cmd == \\"reset\\":\\n        if not args.yes:\\n            print(\\"refusing to reset without --yes\\", file=sys.stderr)\\n            return 2\\n        eng.reset()\\n        print(\\"memory reset\\")\\n    return 0\\n\\n\\nif __name__ == \\"__main__\\":\\n    raise SystemExit(main())\\n", "app/memory30/api.py": "\\"\\"\\"HTTP API for the 30-day memory. Mounted by app/main.py with prefix /api/memory (before the static mount).\\n\\nThin handlers: validate input, call MemoryEngine, return JSON. Mutating routes require the X-Analyst-Token header\\nwhen ANALYST_TOKEN is set in the environment.\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport hmac\\nimport json\\nimport logging\\nimport threading\\nfrom pathlib import Path\\n\\nfrom fastapi import APIRouter, HTTPException, Request\\nfrom pydantic import BaseModel, Field\\n\\nfrom . import config, synth\\nfrom .engine import MemoryEngine\\n\\nlog = logging.getLogger(__name__)\\nrouter = APIRouter(tags=[\\"memory30\\"])\\n\\n_engine: MemoryEngine | None = None\\n_engine_lock = threading.Lock()\\n_busy = threading.Lock()\\n\\n\\ndef get_engine() -> MemoryEngine:\\n    global _engine\\n    with _engine_lock:\\n        if _engine is None:\\n            _engine = MemoryEngine(config.DB_PATH)\\n        return _engine\\n\\n\\ndef _require_token(request: Request) -> None:\\n    token = config.analyst_token()\\n    if not token:\\n        return\\n    given = request.headers.get(\\"x-analyst-token\\", \\"\\")\\n    if not hmac.compare_digest(given.encode(), token.encode()):\\n        raise HTTPException(status_code=401, detail=\\"Missing or wrong X-Analyst-Token\\")\\n\\n\\ndef _safe_paths(paths: list[str] | None) -> list[Path] | None:\\n    \\"\\"\\"Only allow paths inside the project\'s data/ folder.\\"\\"\\"\\n    if not paths:\\n        return None\\n    root = config.DATA_DIR.resolve()\\n    out = []\\n    for p in paths:\\n        rp = (config.ROOT / p).resolve() if not Path(p).is_absolute() else Path(p).resolve()\\n        if root != rp and root not in rp.parents:\\n            raise HTTPException(status_code=422, detail=f\\"Path must be inside data/: {p}\\")\\n        out.append(rp)\\n    return out\\n\\n\\nclass IngestBody(BaseModel):\\n    paths: list[str] | None = None\\n\\n\\nclass SynthBody(BaseModel):\\n    days: int = Field(30, ge=7, le=120)\\n    identities: int = Field(200, ge=5, le=2000)\\n    seed: int = 42\\n    ingest: bool = True\\n    reset_first: bool = False\\n\\n\\nclass PruneBody(BaseModel):\\n    vacuum: bool = False\\n\\n\\n@router.get(\\"/stats\\")\\ndef stats():\\n    return get_engine().stats()\\n\\n\\n@router.get(\\"/identities\\")\\ndef identities(limit: int = 50):\\n    return {\\"identities\\": get_engine().identities(limit)}\\n\\n\\n@router.get(\\"/identity/{identity_id}\\")\\ndef identity(identity_id: str, days: int = 30):\\n    view = get_engine().identity_view(identity_id, days)\\n    if view is None:\\n        raise HTTPException(status_code=404, detail=\\"Identity not found in memory\\")\\n    return view\\n\\n\\n@router.get(\\"/findings\\")\\ndef findings(limit: int = 100, identity: str | None = None):\\n    return {\\"findings\\": get_engine().findings(limit=limit, identity=identity)}\\n\\n\\n@router.get(\\"/evidence\\")\\ndef evidence(ids: str = \\"\\"):\\n    id_list = [i for i in ids.split(\\",\\") if i][:200]\\n    return {\\"events\\": get_engine().evidence_events(id_list)}\\n\\n\\n@router.post(\\"/ingest\\")\\ndef ingest(request: Request, body: IngestBody | None = None):\\n    _require_token(request)\\n    paths = _safe_paths((body or IngestBody()).paths)\\n    if not _busy.acquire(blocking=False):\\n        raise HTTPException(status_code=409, detail=\\"Another memory job is running\\")\\n    try:\\n        return get_engine().ingest_paths(paths)\\n    finally:\\n        _busy.release()\\n\\n\\n@router.post(\\"/synth\\")\\ndef synth_run(request: Request, body: SynthBody | None = None):\\n    _require_token(request)\\n    body = body or SynthBody()\\n    if not _busy.acquire(blocking=False):\\n        raise HTTPException(status_code=409, detail=\\"Another memory job is running\\")\\n    try:\\n        eng = get_engine()\\n        if body.reset_first:\\n            eng.reset()\\n        info = synth.write(config.SYNTH_DIR, body.days, body.identities, body.seed)\\n        out = {\\"generated\\": info}\\n        if body.ingest:\\n            out[\\"ingest\\"] = eng.ingest_paths([config.SYNTH_DIR / \\"okta\\", config.SYNTH_DIR / \\"cloudtrail\\"])\\n            labels = json.loads((config.SYNTH_DIR / \\"labels.json\\").read_text(encoding=\\"utf-8\\"))\\n            out[\\"report\\"] = synth.report(eng, labels)\\n        return out\\n    finally:\\n        _busy.release()\\n\\n\\n@router.get(\\"/report\\")\\ndef report():\\n    lp = config.SYNTH_DIR / \\"labels.json\\"\\n    if not lp.exists():\\n        return {\\"status\\": \\"no_synthetic_labels\\"}\\n    return synth.report(get_engine(), json.loads(lp.read_text(encoding=\\"utf-8\\")))\\n\\n\\n@router.post(\\"/prune\\")\\ndef prune(request: Request, body: PruneBody | None = None):\\n    _require_token(request)\\n    if not _busy.acquire(blocking=False):\\n        raise HTTPException(status_code=409, detail=\\"Another memory job is running\\")\\n    try:\\n        return get_engine().prune(vacuum=(body or PruneBody()).vacuum)\\n    finally:\\n        _busy.release()\\n\\n\\n@router.post(\\"/reset\\")\\ndef reset(request: Request):\\n    _require_token(request)\\n    if not _busy.acquire(blocking=False):\\n        raise HTTPException(status_code=409, detail=\\"Another memory job is running\\")\\n    try:\\n        get_engine().reset()\\n        return {\\"status\\": \\"reset\\"}\\n    finally:\\n        _busy.release()\\n", "app/memory30/catalog.py": "\\"\\"\\"Action categories and attack stages used by the 30-day memory.\\"\\"\\"\\nfrom __future__ import annotations\\n\\n# ---- categories ---------------------------------------------------------------------------------\\nLOGIN = \\"login\\"\\nLOGIN_FAIL = \\"login_fail\\"\\nMFA_DENY = \\"mfa_deny\\"\\nMFA_CHANGE = \\"mfa_change\\"\\nCREDENTIAL = \\"credential\\"\\nDISCOVERY = \\"discovery\\"\\nPRIVESC = \\"privesc\\"\\nDATA_READ = \\"data_read\\"\\nDATA_WRITE = \\"data_write\\"\\nEXFIL_SHARE = \\"exfil_share\\"\\nDEFENSE_EVASION = \\"defense_evasion\\"\\nOTHER_READ = \\"other_read\\"\\nOTHER_WRITE = \\"other_write\\"\\n\\nCT_LOGIN = {\\"ConsoleLogin\\", \\"AssumeRoleWithSAML\\", \\"AssumeRoleWithWebIdentity\\"}\\nCT_MFA_CHANGE = {\\"CreateVirtualMFADevice\\", \\"EnableMFADevice\\", \\"DeactivateMFADevice\\", \\"DeleteVirtualMFADevice\\",\\n                 \\"ResyncMFADevice\\"}\\nCT_CREDENTIAL = {\\"CreateAccessKey\\", \\"UpdateAccessKey\\", \\"CreateLoginProfile\\", \\"UpdateLoginProfile\\",\\n                 \\"CreateServiceSpecificCredential\\", \\"UploadSSHPublicKey\\", \\"ChangePassword\\"}\\nCT_PRIVESC = {\\"AttachUserPolicy\\", \\"AttachRolePolicy\\", \\"AttachGroupPolicy\\", \\"PutUserPolicy\\", \\"PutRolePolicy\\",\\n              \\"PutGroupPolicy\\", \\"CreatePolicyVersion\\", \\"SetDefaultPolicyVersion\\", \\"AddUserToGroup\\",\\n              \\"UpdateAssumeRolePolicy\\", \\"PassRole\\", \\"CreateRole\\", \\"CreateUser\\"}\\nCT_DATA_READ = {\\"GetObject\\", \\"GetSecretValue\\", \\"BatchGetSecretValue\\", \\"Decrypt\\", \\"GetParameter\\", \\"GetParameters\\",\\n                \\"GetParametersByPath\\", \\"SelectObjectContent\\", \\"DownloadDBLogFilePortion\\", \\"Sign\\"}\\nCT_DATA_WRITE = {\\"PutObject\\", \\"DeleteObject\\", \\"DeleteObjects\\", \\"CopyObject\\", \\"UpdateFunctionCode\\",\\n                 \\"PutParameter\\", \\"UpdateSecret\\", \\"PutSecretValue\\", \\"RegisterTaskDefinition\\", \\"UpdateService\\"}\\nCT_EXFIL_SHARE = {\\"ModifySnapshotAttribute\\", \\"ModifyDBSnapshotAttribute\\", \\"ModifyDBClusterSnapshotAttribute\\",\\n                  \\"PutBucketPolicy\\", \\"PutBucketAcl\\", \\"PutBucketReplication\\", \\"DeletePublicAccessBlock\\",\\n                  \\"PutObjectAcl\\", \\"ModifyImageAttribute\\", \\"SharePortfolio\\"}\\nCT_DEFENSE_EVASION = {\\"StopLogging\\", \\"DeleteTrail\\", \\"UpdateTrail\\", \\"PutEventSelectors\\", \\"DeleteDetector\\",\\n                      \\"UpdateDetector\\", \\"DisassociateMembers\\", \\"DeleteFlowLogs\\", \\"DisableKey\\",\\n                      \\"ScheduleKeyDeletion\\", \\"DeleteConfigRule\\", \\"StopConfigurationRecorder\\"}\\nCT_DISCOVERY_EXTRA = {\\"GetAccountAuthorizationDetails\\", \\"GetBucketPolicy\\", \\"GetBucketAcl\\", \\"GetPolicy\\",\\n                      \\"GetPolicyVersion\\", \\"GetRolePolicy\\", \\"GetUserPolicy\\", \\"GetCallerIdentity\\",\\n                      \\"GetBucketLocation\\", \\"SearchResources\\"}\\n\\n\\ndef categorize(source: str, action: str, outcome: str) -> str:\\n    \\"\\"\\"Map a normalized event to one category. Pure function.\\"\\"\\"\\n    a = action or \\"\\"\\n    if source == \\"okta\\":\\n        low = a.lower()\\n        if \\"deny_push\\" in low or \\"mfa.okta_verify.deny\\" in low:\\n            return MFA_DENY\\n        if (\\"factor\\" in low and any(k in low for k in (\\"activate\\", \\"enroll\\", \\"reset\\", \\"update\\", \\"deactivate\\"))) \\\\\\n                or \\"user.mfa.factor\\" in low:\\n            return MFA_CHANGE\\n        if \\"reset_password\\" in low or \\"password.update\\" in low or \\"credential\\" in low:\\n            return CREDENTIAL\\n        if low.startswith(\\"user.session.start\\") or low.startswith(\\"user.authentication\\"):\\n            return LOGIN_FAIL if outcome == \\"failure\\" else LOGIN\\n        if \\"privilege.grant\\" in low or \\"group.user_membership.add\\" in low or \\"app.user_membership.add\\" in low:\\n            return PRIVESC\\n        return OTHER_READ\\n    if a in CT_LOGIN:\\n        return LOGIN_FAIL if outcome == \\"failure\\" else LOGIN\\n    if a in CT_MFA_CHANGE:\\n        return MFA_CHANGE\\n    if a in CT_CREDENTIAL:\\n        return CREDENTIAL\\n    if a in CT_PRIVESC:\\n        return PRIVESC\\n    if a in CT_EXFIL_SHARE:\\n        return EXFIL_SHARE\\n    if a in CT_DEFENSE_EVASION:\\n        return DEFENSE_EVASION\\n    if a in CT_DATA_READ:\\n        return DATA_READ\\n    if a in CT_DATA_WRITE:\\n        return DATA_WRITE\\n    if a in CT_DISCOVERY_EXTRA or a.startswith((\\"List\\", \\"Describe\\")):\\n        return DISCOVERY\\n    if a.startswith((\\"Get\\", \\"Head\\", \\"Lookup\\", \\"Search\\")):\\n        return OTHER_READ\\n    return OTHER_WRITE\\n\\n\\n# ---- attack-stage hits ----------------------------------------------------------------------------\\n# kind -> (kill-chain stage, severity 0..1, plain-English label)\\nHIT_KINDS: dict[str, tuple[str, float, str]] = {\\n    \\"new_network\\": (\\"initial_access\\", 0.35, \\"activity from a network never used by this identity\\"),\\n    \\"proxy_login\\": (\\"initial_access\\", 0.50, \\"login through a proxy / anonymizing network\\"),\\n    \\"mfa_change\\": (\\"persistence\\", 0.60, \\"MFA device registration or change\\"),\\n    \\"credential\\": (\\"persistence\\", 0.50, \\"new credentials created (access key, password, login profile)\\"),\\n    \\"discovery\\": (\\"discovery\\", 0.25, \\"burst of discovery calls across services\\"),\\n    \\"privesc\\": (\\"privilege_escalation\\", 0.70, \\"permissions or roles granted\\"),\\n    \\"read_staircase\\": (\\"collection\\", 0.40, \\"sensitive data reads growing week over week\\"),\\n    \\"modify_sensitive\\": (\\"impact\\", 0.70, \\"change to a sensitive / production resource\\"),\\n    \\"exfil_share\\": (\\"exfiltration\\", 0.80, \\"data or snapshot shared outside / made public\\"),\\n    \\"defense_evasion\\": (\\"defense_evasion\\", 0.80, \\"logging or detection disabled\\"),\\n}\\n\\nSTAGE_ORDER = [\\"initial_access\\", \\"persistence\\", \\"discovery\\", \\"privilege_escalation\\", \\"collection\\",\\n               \\"defense_evasion\\", \\"impact\\", \\"exfiltration\\"]\\n\\n# category -> hit kind for per-event hits (others are computed per day / per week)\\nCATEGORY_HIT = {\\n    MFA_CHANGE: \\"mfa_change\\",\\n    CREDENTIAL: \\"credential\\",\\n    PRIVESC: \\"privesc\\",\\n    EXFIL_SHARE: \\"exfil_share\\",\\n    DEFENSE_EVASION: \\"defense_evasion\\",\\n}\\n", "app/memory30/config.py": "\\"\\"\\"Configuration for the 30-day memory. Every value can be overridden with an environment variable MEM30_<NAME>.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport os\\nfrom pathlib import Path\\n\\nROOT = Path(__file__).resolve().parents[2]\\nDATA_DIR = ROOT / \\"data\\"\\n\\n\\ndef _env_int(name: str, default: int) -> int:\\n    raw = os.environ.get(f\\"MEM30_{name}\\")\\n    try:\\n        return int(raw) if raw not in (None, \\"\\") else default\\n    except ValueError:\\n        return default\\n\\n\\ndef _env_float(name: str, default: float) -> float:\\n    raw = os.environ.get(f\\"MEM30_{name}\\")\\n    try:\\n        return float(raw) if raw not in (None, \\"\\") else default\\n    except ValueError:\\n        return default\\n\\n\\nDB_PATH = Path(os.environ.get(\\"MEM30_DB_PATH\\") or (DATA_DIR / \\"memory30.sqlite\\"))\\n\\n# Tiered retention\\nRAW_EVENT_RETENTION_DAYS = _env_int(\\"RAW_EVENT_RETENTION_DAYS\\", 7)     # raw events (non-evidence)\\nMEMORY_RETENTION_DAYS = _env_int(\\"MEMORY_RETENTION_DAYS\\", 30)          # daily summaries, hits, networks\\n\\n# Chain linking\\nCHAIN_MAX_GAP_DAYS = _env_int(\\"CHAIN_MAX_GAP_DAYS\\", 14)                # max gap between two linked steps\\nCHAIN_MAX_SPAN_DAYS = _env_int(\\"CHAIN_MAX_SPAN_DAYS\\", 30)              # max length of one chain\\nFINDING_MIN_STAGES = _env_int(\\"FINDING_MIN_STAGES\\", 3)                 # distinct kill-chain stages for a finding\\nFINDING_MIN_RISK = _env_float(\\"FINDING_MIN_RISK\\", 70.0)                # or a risk at least this high\\nSINGLE_STEP_MIN_SEVERITY = _env_float(\\"SINGLE_STEP_MIN_SEVERITY\\", 0.8)  # one step alone must be critical\\nSHARED_TARGET_MIN_WRITERS = _env_int(\\"SHARED_TARGET_MIN_WRITERS\\", 3)   # team resource if >= N other writers\\nCHAIN_STEP_BONUS = 0.15\\nCHAIN_FACTOR_CAP = 1.6\\n\\n# Baselines\\nMIN_HISTORY_DAYS = _env_int(\\"MIN_HISTORY_DAYS\\", 3)                     # before \\"new network\\" can fire\\nDISCOVERY_DAILY_MIN = _env_int(\\"DISCOVERY_DAILY_MIN\\", 5)               # discovery calls per day\\nDISCOVERY_SERVICES_MIN = _env_int(\\"DISCOVERY_SERVICES_MIN\\", 3)         # distinct services per day\\nSTAIRCASE_WEEKS = 3                                                    # consecutive week-over-week increases\\nSTAIRCASE_GROWTH = _env_float(\\"STAIRCASE_GROWTH\\", 0.4)                 # +40 % per week\\nSTAIRCASE_MIN_LAST_WEEK = _env_int(\\"STAIRCASE_MIN_LAST_WEEK\\", 20)      # ignore tiny volumes\\nPEER_PERCENTILE = 0.9\\nPEER_MIN_IDENTITIES = 5\\n\\n# Identity risk decay\\nHALF_LIFE_HOURS = _env_float(\\"HALF_LIFE_HOURS\\", 24.0)\\n\\nSENSITIVE_MARKERS = tuple(\\n    m.strip().lower()\\n    for m in os.environ.get(\\n        \\"MEM30_SENSITIVE_MARKERS\\",\\n        \\"prod,finance,secret,pii,payroll,kms,signing,customer,ledger,wallet\\",\\n    ).split(\\",\\")\\n    if m.strip()\\n)\\n\\nRAW_MAX_CHARS = 4000            # raw JSON kept per event (truncated)\\nEVIDENCE_MAX_IDS = 60           # evidence ids kept per finding\\nHIT_MAX_IDS = 10                # event ids kept per hit\\n\\nDEFAULT_SOURCES = [DATA_DIR / \\"raw\\" / \\"okta\\", DATA_DIR / \\"raw\\" / \\"cloudtrail\\", DATA_DIR / \\"input\\"]\\nSYNTH_DIR = DATA_DIR / \\"synth\\"\\n\\n\\ndef analyst_token() -> str:\\n    \\"\\"\\"Read at call time so tests and .env changes apply without restart.\\"\\"\\"\\n    return os.environ.get(\\"ANALYST_TOKEN\\", \\"\\")\\n", "app/memory30/engine.py": "\\"\\"\\"MemoryEngine: tiered 30-day identity memory and slow attack-chain linking.\\n\\nDesign:\\n- Everything lives in SQLite, so the memory survives restarts by construction.\\n- Time is DATA time (event timestamps), never the wall clock, so replaying old or synthetic data behaves exactly\\n  like live data. The \\"data clock\\" is the newest event time seen.\\n- Ingest is idempotent (event_id primary key); recomputation of chains/findings is deterministic.\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport hashlib\\nimport json\\nimport logging\\nimport math\\nimport sqlite3\\nfrom datetime import date, datetime, timedelta, timezone\\nfrom pathlib import Path\\nfrom typing import Any, Iterable\\n\\nfrom . import catalog, config\\nfrom .normalize import fmt_time, load_paths, normalize, parse_time\\nfrom .store import TABLES, Store\\n\\nlog = logging.getLogger(__name__)\\n\\n_DAILY_COLS = {\\n    catalog.LOGIN: \\"logins\\",\\n    catalog.LOGIN_FAIL: \\"login_failures\\",\\n    catalog.DISCOVERY: \\"discovery\\",\\n    catalog.DATA_READ: \\"data_reads\\",\\n    catalog.DATA_WRITE: \\"writes\\",\\n    catalog.OTHER_WRITE: \\"writes\\",\\n    catalog.PRIVESC: \\"privesc\\",\\n    catalog.CREDENTIAL: \\"credential\\",\\n    catalog.MFA_CHANGE: \\"credential\\",\\n    catalog.EXFIL_SHARE: \\"exfil\\",\\n    catalog.DEFENSE_EVASION: \\"evasion\\",\\n}\\n\\n\\ndef _day(d: str) -> date:\\n    return date.fromisoformat(d[:10])\\n\\n\\ndef _decay(value: float, hours: float) -> float:\\n    if value <= 0 or hours <= 0:\\n        return max(value, 0.0)\\n    return value * math.exp(-math.log(2) * hours / max(config.HALF_LIFE_HOURS, 0.1))\\n\\n\\nclass MemoryEngine:\\n    def __init__(self, db_path: Path | str | None = None):\\n        self.store = Store(db_path or config.DB_PATH)\\n\\n    # ================================================================ ingest\\n    def ingest_paths(self, paths: Iterable[Path | str] | None = None) -> dict:\\n        sources = [Path(p) for p in (paths or config.DEFAULT_SOURCES)]\\n        existing = [p for p in sources if p.exists()]\\n        records, info = load_paths(existing)\\n        out = self.ingest_records(records)\\n        out.update({\\"files\\": info[\\"files\\"], \\"bad_files\\": info[\\"bad_files\\"],\\n                    \\"paths\\": [str(p) for p in existing],\\n                    \\"missing_paths\\": [str(p) for p in sources if not p.exists()]})\\n        return out\\n\\n    def ingest_records(self, records: Iterable[dict]) -> dict:\\n        received = 0\\n        norm: list[dict] = []\\n        for r in records:\\n            received += 1\\n            n = normalize(r)\\n            if n is not None:\\n                norm.append(n)\\n        norm.sort(key=lambda n: (n[\\"time\\"], n[\\"event_id\\"]))\\n        inserted = duplicates = new_hits = 0\\n        touched_days: set[tuple[str, str]] = set()\\n        touched_ids: set[str] = set()\\n        findings_updated = 0\\n        with self.store.tx() as c:\\n            for n in norm:\\n                if not self._insert_event(c, n):\\n                    duplicates += 1\\n                    continue\\n                inserted += 1\\n                new_hits += self._per_event(c, n)\\n                touched_days.add((n[\\"identity\\"], n[\\"day\\"]))\\n                touched_ids.add(n[\\"identity\\"])\\n            for identity, day in sorted(touched_days):\\n                new_hits += self._discovery_hit(c, identity, day)\\n            peer_cache: dict[str, list[int]] = {}\\n            for identity in sorted(touched_ids):\\n                new_hits += self._staircase_hit(c, identity, peer_cache)\\n            for identity in sorted(touched_ids):\\n                findings_updated += self._evaluate_chains(c, identity)\\n            if norm:\\n                newest = norm[-1][\\"time\\"]\\n                row = c.execute(\\"SELECT value FROM meta WHERE key=\'data_clock\'\\").fetchone()\\n                if row is None or newest > row[\\"value\\"]:\\n                    c.execute(\\"INSERT INTO meta(key, value) VALUES(\'data_clock\', ?) \\"\\n                              \\"ON CONFLICT(key) DO UPDATE SET value=excluded.value\\", (newest,))\\n        return {\\n            \\"received\\": received,\\n            \\"normalized\\": len(norm),\\n            \\"skipped\\": received - len(norm),\\n            \\"inserted\\": inserted,\\n            \\"duplicates\\": duplicates,\\n            \\"identities_touched\\": len(touched_ids),\\n            \\"new_hits\\": new_hits,\\n            \\"findings_updated\\": findings_updated,\\n            \\"data_clock\\": self.data_clock(),\\n        }\\n\\n    # ---------------------------------------------------------------- per event\\n    @staticmethod\\n    def _insert_event(c: sqlite3.Connection, n: dict) -> bool:\\n        cur = c.execute(\\n            \\"INSERT OR IGNORE INTO events(event_id, time, day, source, identity, action, category, service, \\"\\n            \\"outcome, ip, net, country, is_proxy, resource, sensitive, read_only, session, raw) \\"\\n            \\"VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)\\",\\n            (n[\\"event_id\\"], n[\\"time\\"], n[\\"day\\"], n[\\"source\\"], n[\\"identity\\"], n[\\"action\\"], n[\\"category\\"],\\n             n.get(\\"service\\"), n[\\"outcome\\"], n.get(\\"ip\\"), n.get(\\"net\\"), n.get(\\"country\\"), int(bool(n.get(\\"is_proxy\\"))),\\n             n.get(\\"resource\\"), int(bool(n.get(\\"sensitive\\"))), int(bool(n.get(\\"read_only\\"))), n.get(\\"session\\"),\\n             n.get(\\"raw\\")))\\n        return cur.rowcount == 1\\n\\n    def _per_event(self, c: sqlite3.Connection, n: dict) -> int:\\n        identity, day, t = n[\\"identity\\"], n[\\"day\\"], n[\\"time\\"]\\n        meta = c.execute(\\"SELECT first_seen FROM identity_meta WHERE identity=?\\", (identity,)).fetchone()\\n        history_days = 0.0\\n        if meta:\\n            history_days = (parse_time(t) - parse_time(meta[\\"first_seen\\"])).total_seconds() / 86400\\n        c.execute(\\n            \\"INSERT INTO identity_meta(identity, first_seen, last_seen) VALUES(?, ?, ?) \\"\\n            \\"ON CONFLICT(identity) DO UPDATE SET first_seen=min(first_seen, excluded.first_seen), \\"\\n            \\"last_seen=max(last_seen, excluded.last_seen)\\", (identity, t, t))\\n\\n        # daily summary\\n        incr = {\\"events\\": 1}\\n        col = _DAILY_COLS.get(n[\\"category\\"])\\n        if col:\\n            incr[col] = incr.get(col, 0) + 1\\n        if n[\\"category\\"] == catalog.DATA_READ and n.get(\\"sensitive\\"):\\n            incr[\\"sensitive_reads\\"] = 1\\n        hits = 0\\n        new_net = False\\n        if n.get(\\"net\\"):\\n            row = c.execute(\\"SELECT 1 FROM identity_networks WHERE identity=? AND net=?\\",\\n                            (identity, n[\\"net\\"])).fetchone()\\n            if row is None:\\n                c.execute(\\"INSERT INTO identity_networks(identity, net, first_seen, last_seen, count) \\"\\n                          \\"VALUES(?, ?, ?, ?, 1)\\", (identity, n[\\"net\\"], t, t))\\n                new_net = history_days >= config.MIN_HISTORY_DAYS\\n            else:\\n                c.execute(\\"UPDATE identity_networks SET last_seen=max(last_seen, ?), count=count+1 \\"\\n                          \\"WHERE identity=? AND net=?\\", (t, identity, n[\\"net\\"]))\\n        if new_net:\\n            incr[\\"new_networks\\"] = 1\\n        cols = \\", \\".join(incr)\\n        placeholders = \\", \\".join(\\"?\\" for _ in incr)\\n        updates = \\", \\".join(f\\"{k}={k}+excluded.{k}\\" for k in incr)\\n        c.execute(f\\"INSERT INTO identity_daily(identity, day, {cols}) VALUES(?, ?, {placeholders}) \\"\\n                  f\\"ON CONFLICT(identity, day) DO UPDATE SET {updates}\\", (identity, day, *incr.values()))\\n        if n[\\"category\\"] == catalog.DISCOVERY and n.get(\\"service\\"):\\n            c.execute(\\"INSERT OR IGNORE INTO daily_services(identity, day, service) VALUES(?, ?, ?)\\",\\n                      (identity, day, n[\\"service\\"]))\\n\\n        # stage hits\\n        if new_net:\\n            hits += self._add_hit(c, identity, \\"new_network\\", day, t, t, [n[\\"event_id\\"]],\\n                                  {\\"net\\": n.get(\\"net\\"), \\"ip\\": n.get(\\"ip\\")})\\n        if n.get(\\"is_proxy\\") and n[\\"category\\"] in (catalog.LOGIN, catalog.LOGIN_FAIL):\\n            hits += self._add_hit(c, identity, \\"proxy_login\\", day, t, t, [n[\\"event_id\\"]], {\\"ip\\": n.get(\\"ip\\")})\\n        kind = catalog.CATEGORY_HIT.get(n[\\"category\\"])\\n        if kind:\\n            hits += self._add_hit(c, identity, kind, day, t, t, [n[\\"event_id\\"]],\\n                                  {\\"action\\": n[\\"action\\"], \\"resource\\": n.get(\\"resource\\"), \\"outcome\\": n[\\"outcome\\"]})\\n        if n[\\"category\\"] in (catalog.DATA_WRITE, catalog.OTHER_WRITE) and n.get(\\"resource\\"):\\n            target = self._target_of(n.get(\\"service\\"), n[\\"resource\\"])\\n            seen = c.execute(\\"SELECT 1 FROM identity_write_targets WHERE identity=? AND target=?\\",\\n                             (identity, target)).fetchone()\\n            if seen is None:\\n                c.execute(\\"INSERT INTO identity_write_targets(identity, target, first_seen, last_seen, count) \\"\\n                          \\"VALUES(?, ?, ?, ?, 1)\\", (identity, target, t, t))\\n            else:\\n                c.execute(\\"UPDATE identity_write_targets SET last_seen=max(last_seen, ?), count=count+1 \\"\\n                          \\"WHERE identity=? AND target=?\\", (t, identity, target))\\n            # only a FIRST-EVER write to a sensitive target (after the baseline period) is suspicious;\\n            # routine writes to the identity\'s own sensitive resources are normal work\\n            peers = 0\\n            if seen is None and n.get(\\"sensitive\\") and history_days >= config.MIN_HISTORY_DAYS:\\n                peers = c.execute(\\"SELECT COUNT(*) FROM identity_write_targets WHERE target=? AND identity<>?\\",\\n                                  (target, identity)).fetchone()[0]\\n            if seen is None and n.get(\\"sensitive\\") and history_days >= config.MIN_HISTORY_DAYS \\\\\\n                    and peers < config.SHARED_TARGET_MIN_WRITERS:\\n                hits += self._add_hit(c, identity, \\"modify_sensitive\\", day, t, t, [n[\\"event_id\\"]],\\n                                      {\\"action\\": n[\\"action\\"], \\"resource\\": n.get(\\"resource\\"),\\n                                       \\"reason\\": \\"first write by this identity to a sensitive resource\\",\\n                                       \\"other_writers\\": peers})\\n        return hits\\n\\n    @staticmethod\\n    def _target_of(service: str | None, resource: str) -> str:\\n        \\"\\"\\"Write-baseline target: the bucket for S3 objects, otherwise the full resource name / ARN.\\"\\"\\"\\n        if service == \\"s3\\" and not resource.startswith(\\"arn:\\"):\\n            return resource.split(\\"/\\", 1)[0]\\n        return resource\\n\\n    @staticmethod\\n    def _add_hit(c: sqlite3.Connection, identity: str, kind: str, day: str, first_time: str, last_time: str,\\n                 event_ids: list[str], detail: dict | None) -> int:\\n        stage, severity, _label = catalog.HIT_KINDS[kind]\\n        row = c.execute(\\"SELECT first_time, last_time, event_ids FROM chain_hits WHERE identity=? AND kind=? \\"\\n                        \\"AND day=?\\", (identity, kind, day)).fetchone()\\n        if row is None:\\n            c.execute(\\"INSERT INTO chain_hits(identity, kind, day, stage, severity, first_time, last_time, \\"\\n                      \\"event_ids, detail) VALUES(?,?,?,?,?,?,?,?,?)\\",\\n                      (identity, kind, day, stage, severity, first_time, last_time,\\n                       json.dumps(event_ids[: config.HIT_MAX_IDS]), json.dumps(detail or {}, default=str)))\\n            return 1\\n        ids = json.loads(row[\\"event_ids\\"])\\n        for e in event_ids:\\n            if e not in ids and len(ids) < config.HIT_MAX_IDS:\\n                ids.append(e)\\n        c.execute(\\"UPDATE chain_hits SET first_time=min(first_time, ?), last_time=max(last_time, ?), event_ids=? \\"\\n                  \\"WHERE identity=? AND kind=? AND day=?\\",\\n                  (first_time, last_time, json.dumps(ids), identity, kind, day))\\n        return 0\\n\\n    # ---------------------------------------------------------------- per day / per week\\n    def _discovery_hit(self, c: sqlite3.Connection, identity: str, day: str) -> int:\\n        row = c.execute(\\"SELECT discovery FROM identity_daily WHERE identity=? AND day=?\\", (identity, day)).fetchone()\\n        if not row or row[\\"discovery\\"] <= 0:\\n            return 0\\n        services = c.execute(\\"SELECT COUNT(*) AS n FROM daily_services WHERE identity=? AND day=?\\",\\n                             (identity, day)).fetchone()[\\"n\\"]\\n        if row[\\"discovery\\"] < config.DISCOVERY_DAILY_MIN or services < config.DISCOVERY_SERVICES_MIN:\\n            return 0\\n        # baseline = this identity\'s average discovery on its NORMAL days of the last 30 days\\n        # (days already flagged are excluded, so an attacker cannot teach the baseline that recon is normal)\\n        start = (_day(day) - timedelta(days=config.MEMORY_RETENTION_DAYS)).isoformat()\\n        base = c.execute(\\n            \\"SELECT AVG(d.discovery) AS a, COUNT(*) AS n FROM identity_daily d WHERE d.identity=? AND d.day>=? \\"\\n            \\"AND d.day<? AND NOT EXISTS (SELECT 1 FROM chain_hits h WHERE h.identity=d.identity AND h.day=d.day)\\",\\n            (identity, start, day)).fetchone()\\n        baseline = float(base[\\"a\\"] or 0.0) if base[\\"n\\"] else 0.0\\n        if row[\\"discovery\\"] < 3.0 * max(baseline, 1.0):\\n            return 0\\n        evs = c.execute(\\"SELECT event_id, time FROM events WHERE identity=? AND day=? AND category=? \\"\\n                        \\"ORDER BY time LIMIT ?\\", (identity, day, catalog.DISCOVERY, config.HIT_MAX_IDS)).fetchall()\\n        if not evs:\\n            return 0\\n        return self._add_hit(c, identity, \\"discovery\\", day, evs[0][\\"time\\"], evs[-1][\\"time\\"],\\n                             [e[\\"event_id\\"] for e in evs], {\\"calls\\": row[\\"discovery\\"], \\"services\\": services})\\n\\n    def _staircase_hit(self, c: sqlite3.Connection, identity: str, peer_cache: dict[str, list[int]]) -> int:\\n        meta = c.execute(\\"SELECT last_seen FROM identity_meta WHERE identity=?\\", (identity,)).fetchone()\\n        if not meta:\\n            return 0\\n        ref = _day(meta[\\"last_seen\\"])\\n        windows = []\\n        for k in range(config.STAIRCASE_WEEKS + 1):\\n            end = ref - timedelta(days=7 * k)\\n            start = end - timedelta(days=6)\\n            windows.append((start.isoformat(), end.isoformat()))\\n        windows.reverse()  # oldest -> newest\\n        sums = []\\n        for start, end in windows:\\n            r = c.execute(\\"SELECT COALESCE(SUM(sensitive_reads), 0) AS s FROM identity_daily WHERE identity=? \\"\\n                          \\"AND day BETWEEN ? AND ?\\", (identity, start, end)).fetchone()\\n            sums.append(int(r[\\"s\\"]))\\n        if sums[0] <= 0 or sums[-1] < config.STAIRCASE_MIN_LAST_WEEK:\\n            return 0\\n        if any(sums[i + 1] < sums[i] * (1 + config.STAIRCASE_GROWTH) for i in range(len(sums) - 1)):\\n            return 0\\n        # peer check: last week must exceed the peer percentile\\n        key = windows[-1][1]\\n        if key not in peer_cache:\\n            rows = c.execute(\\"SELECT identity, SUM(sensitive_reads) AS s FROM identity_daily WHERE day BETWEEN ? AND ? \\"\\n                             \\"GROUP BY identity\\", windows[-1]).fetchall()\\n            peer_cache[key] = [(r[\\"identity\\"], int(r[\\"s\\"] or 0)) for r in rows]\\n        peers = sorted(s for i, s in peer_cache[key] if i != identity)\\n        if len(peers) >= config.PEER_MIN_IDENTITIES:\\n            p = peers[int(config.PEER_PERCENTILE * (len(peers) - 1))]\\n            if sums[-1] <= p:\\n                return 0\\n        ids: list[str] = []\\n        times: list[str] = []\\n        for start, end in windows:\\n            evs = c.execute(\\"SELECT event_id, time FROM events WHERE identity=? AND day BETWEEN ? AND ? AND \\"\\n                            \\"category=? AND sensitive=1 ORDER BY time LIMIT 2\\",\\n                            (identity, start, end, catalog.DATA_READ)).fetchall()\\n            ids.extend(e[\\"event_id\\"] for e in evs)\\n            times.extend(e[\\"time\\"] for e in evs)\\n        last_week = c.execute(\\"SELECT MIN(time) AS a, MAX(time) AS b FROM events WHERE identity=? AND day BETWEEN ? \\"\\n                              \\"AND ? AND category=? AND sensitive=1\\", (identity, *windows[-1],\\n                                                                       catalog.DATA_READ)).fetchone()\\n        if not ids or not last_week[\\"a\\"]:\\n            return 0\\n        return self._add_hit(c, identity, \\"read_staircase\\", ref.isoformat(), last_week[\\"a\\"], last_week[\\"b\\"], ids,\\n                             {\\"weekly_sensitive_reads\\": sums})\\n\\n    # ---------------------------------------------------------------- chains and findings\\n    def _evaluate_chains(self, c: sqlite3.Connection, identity: str) -> int:\\n        hits = c.execute(\\"SELECT * FROM chain_hits WHERE identity=? ORDER BY first_time, kind\\",\\n                         (identity,)).fetchall()\\n        chains: list[list[sqlite3.Row]] = []\\n        cur: list[sqlite3.Row] = []\\n        cur_start = cur_last = None\\n        for h in hits:\\n            ft, lt = parse_time(h[\\"first_time\\"]), parse_time(h[\\"last_time\\"])\\n            if cur and (ft - cur_last).total_seconds() / 86400 <= config.CHAIN_MAX_GAP_DAYS \\\\\\n                    and (lt - cur_start).total_seconds() / 86400 <= config.CHAIN_MAX_SPAN_DAYS:\\n                cur.append(h)\\n                cur_last = max(cur_last, lt)\\n            else:\\n                if cur:\\n                    chains.append(cur)\\n                cur, cur_start, cur_last = [h], ft, lt\\n        if cur:\\n            chains.append(cur)\\n\\n        updated = 0\\n        identity_risk, risk_time = 0.0, None\\n        for chain in chains:\\n            stage_max: dict[str, float] = {}\\n            day_risk: dict[str, float] = {}\\n            risk = 0.0\\n            for h in chain:\\n                stage_max[h[\\"stage\\"]] = max(stage_max.get(h[\\"stage\\"], 0.0), h[\\"severity\\"])\\n                risk = self._chain_risk(stage_max)\\n                day_risk[h[\\"day\\"]] = max(day_risk.get(h[\\"day\\"], 0.0), risk)\\n            for d, r in day_risk.items():\\n                c.execute(\\"UPDATE identity_daily SET max_risk=max(max_risk, ?) WHERE identity=? AND day=?\\",\\n                          (r, identity, d))\\n            chain_last = max(h[\\"last_time\\"] for h in chain)\\n            if risk_time is not None:\\n                hours = (parse_time(chain_last) - parse_time(risk_time)).total_seconds() / 3600\\n                identity_risk = _decay(identity_risk, hours)\\n            identity_risk = max(identity_risk, risk)\\n            risk_time = chain_last if risk_time is None else max(risk_time, chain_last)\\n            if self._is_finding(stage_max, risk):\\n                self._upsert_finding(c, identity, chain, stage_max, risk)\\n                updated += 1\\n        c.execute(\\"UPDATE identity_meta SET risk=?, risk_updated=? WHERE identity=?\\",\\n                  (round(identity_risk, 1), risk_time, identity))\\n        return updated\\n\\n    @staticmethod\\n    def _is_finding(stage_max: dict[str, float], risk: float) -> bool:\\n        \\"\\"\\"Memory findings are about multi-step chains; single steps are left to the real-time detectors\\n        unless they are critical on their own (exfiltration, defense evasion).\\"\\"\\"\\n        n = len(stage_max)\\n        if n >= config.FINDING_MIN_STAGES:\\n            return True\\n        if n >= 2 and risk >= config.FINDING_MIN_RISK:\\n            return True\\n        return n == 1 and max(stage_max.values()) >= config.SINGLE_STEP_MIN_SEVERITY\\n\\n    @staticmethod\\n    def _chain_risk(stage_max: dict[str, float]) -> float:\\n        p = 1.0\\n        for s in stage_max.values():\\n            p *= (1.0 - s)\\n        factor = min(config.CHAIN_FACTOR_CAP, 1.0 + config.CHAIN_STEP_BONUS * (len(stage_max) - 1))\\n        return round(min(100.0, 100.0 * (1.0 - p) * factor), 1)\\n\\n    def _upsert_finding(self, c: sqlite3.Connection, identity: str, chain: list[sqlite3.Row],\\n                        stage_max: dict[str, float], risk: float) -> None:\\n        first = chain[0]\\n        fid = \\"MEM-\\" + hashlib.sha1(f\\"{identity}|{first[\'kind\']}|{first[\'day\']}\\".encode()).hexdigest()[:10]\\n        steps, evidence = [], []\\n        for h in chain:\\n            ids = json.loads(h[\\"event_ids\\"])\\n            steps.append({\\"day\\": h[\\"day\\"], \\"kind\\": h[\\"kind\\"], \\"stage\\": h[\\"stage\\"], \\"severity\\": h[\\"severity\\"],\\n                          \\"label\\": catalog.HIT_KINDS[h[\\"kind\\"]][2], \\"event_ids\\": ids,\\n                          \\"detail\\": json.loads(h[\\"detail\\"] or \\"{}\\")})\\n            for e in ids:\\n                if e not in evidence and len(evidence) < config.EVIDENCE_MAX_IDS:\\n                    evidence.append(e)\\n        for i in range(0, len(evidence), 500):\\n            chunk = evidence[i:i + 500]\\n            c.execute(f\\"UPDATE events SET evidence=1 WHERE event_id IN ({\',\'.join(\'?\' * len(chunk))})\\", chunk)\\n        ev_days = {s[\\"day\\"] for s in steps}\\n        if evidence:\\n            rows = c.execute(f\\"SELECT DISTINCT day FROM events WHERE event_id IN ({\',\'.join(\'?\' * len(evidence))})\\",\\n                             evidence).fetchall()\\n            ev_days |= {r[\\"day\\"] for r in rows}\\n        stages = [s for s in catalog.STAGE_ORDER if s in stage_max]\\n        first_time = min(h[\\"first_time\\"] for h in chain)\\n        last_time = max(h[\\"last_time\\"] for h in chain)\\n        narrative = self._narrative(identity, steps, len(ev_days), first_time, last_time, risk)\\n        now = fmt_time(datetime.now(timezone.utc))\\n        c.execute(\\n            \\"INSERT INTO findings(finding_id, identity, risk, stages, steps, evidence, first_time, last_time, \\"\\n            \\"days_spanned, narrative, updated) VALUES(?,?,?,?,?,?,?,?,?,?,?) \\"\\n            \\"ON CONFLICT(finding_id) DO UPDATE SET risk=excluded.risk, stages=excluded.stages, steps=excluded.steps, \\"\\n            \\"evidence=excluded.evidence, first_time=excluded.first_time, last_time=excluded.last_time, \\"\\n            \\"days_spanned=excluded.days_spanned, narrative=excluded.narrative, updated=excluded.updated\\",\\n            (fid, identity, risk, json.dumps(stages), json.dumps(steps, default=str), json.dumps(evidence),\\n             first_time, last_time, len(ev_days), narrative, now))\\n\\n    @staticmethod\\n    def _narrative(identity: str, steps: list[dict], days: int, first_time: str, last_time: str,\\n                   risk: float) -> str:\\n        groups: dict[str, list[str]] = {}\\n        for s in steps:\\n            groups.setdefault(s[\\"kind\\"], []).append(s[\\"day\\"])\\n        parts = []\\n        for kind, ds in groups.items():\\n            label = catalog.HIT_KINDS[kind][2]\\n            if len(ds) == 1:\\n                parts.append(f\\"{label} ({ds[0]})\\")\\n            else:\\n                parts.append(f\\"{label} ({ds[0]} to {ds[-1]}, on {len(ds)} days)\\")\\n        return (f\\"Over {days} day(s) between {first_time[:10]} and {last_time[:10]}, {identity} showed \\"\\n                f\\"{len({s[\'stage\'] for s in steps})} attack stage(s): \\" + \\"; \\".join(parts)\\n                + f\\". Linked by the 30-day memory into one chain. Combined risk {risk:.0f}/100.\\")\\n\\n    # ================================================================ retention\\n    def prune(self, now: datetime | None = None, vacuum: bool = False) -> dict:\\n        now = now or parse_time(self.data_clock()) or datetime.now(timezone.utc)\\n        cut_raw = fmt_time(now - timedelta(days=config.RAW_EVENT_RETENTION_DAYS))\\n        cut_mem_t = fmt_time(now - timedelta(days=config.MEMORY_RETENTION_DAYS))\\n        cut_mem_d = (now - timedelta(days=config.MEMORY_RETENTION_DAYS)).strftime(\\"%Y-%m-%d\\")\\n        out: dict[str, Any] = {\\"now\\": fmt_time(now), \\"raw_cutoff\\": cut_raw, \\"memory_cutoff\\": cut_mem_t}\\n        with self.store.tx() as c:\\n            out[\\"events_deleted\\"] = c.execute(\\"DELETE FROM events WHERE time < ? AND evidence = 0\\",\\n                                              (cut_raw,)).rowcount\\n            out[\\"daily_deleted\\"] = c.execute(\\"DELETE FROM identity_daily WHERE day < ?\\", (cut_mem_d,)).rowcount\\n            out[\\"services_deleted\\"] = c.execute(\\"DELETE FROM daily_services WHERE day < ?\\", (cut_mem_d,)).rowcount\\n            out[\\"hits_deleted\\"] = c.execute(\\"DELETE FROM chain_hits WHERE last_time < ?\\", (cut_mem_t,)).rowcount\\n            out[\\"networks_deleted\\"] = c.execute(\\"DELETE FROM identity_networks WHERE last_seen < ?\\",\\n                                                (cut_mem_t,)).rowcount\\n            out[\\"write_targets_deleted\\"] = c.execute(\\"DELETE FROM identity_write_targets WHERE last_seen < ?\\",\\n                                                     (cut_mem_t,)).rowcount\\n            out[\\"evidence_kept\\"] = c.execute(\\"SELECT COUNT(*) FROM events WHERE evidence=1\\").fetchone()[0]\\n            out[\\"findings_kept\\"] = c.execute(\\"SELECT COUNT(*) FROM findings\\").fetchone()[0]\\n        self.store.checkpoint()\\n        if vacuum:\\n            self.store.vacuum()\\n        self.store.set_meta(\\"last_prune\\", out[\\"now\\"])\\n        return out\\n\\n    # ================================================================ views\\n    def data_clock(self) -> str | None:\\n        return self.store.get_meta(\\"data_clock\\")\\n\\n    def current_risk(self, risk: float, risk_updated: str | None) -> float:\\n        clock = parse_time(self.data_clock())\\n        if not risk_updated or not clock:\\n            return round(risk, 1)\\n        hours = (clock - parse_time(risk_updated)).total_seconds() / 3600\\n        return round(_decay(risk, hours), 1)\\n\\n    def stats(self) -> dict:\\n        rows = {t: self.store.one(f\\"SELECT COUNT(*) AS n FROM {t}\\")[\\"n\\"] for t in TABLES}\\n        evidence = self.store.one(\\"SELECT COUNT(*) AS n FROM events WHERE evidence=1\\")[\\"n\\"]\\n        span = self.store.one(\\"SELECT MIN(day) AS a, MAX(day) AS b FROM identity_daily\\")\\n        return {\\n            \\"db_path\\": str(self.store.path),\\n            \\"db_size_bytes\\": self.store.size_bytes(),\\n            \\"db_size_mb\\": round(self.store.size_bytes() / 1_048_576, 2),\\n            \\"rows\\": rows,\\n            \\"evidence_events\\": evidence,\\n            \\"memory_days\\": {\\"first\\": span[\\"a\\"], \\"last\\": span[\\"b\\"]},\\n            \\"data_clock\\": self.data_clock(),\\n            \\"last_prune\\": self.store.get_meta(\\"last_prune\\"),\\n            \\"retention\\": {\\"raw_event_days\\": config.RAW_EVENT_RETENTION_DAYS,\\n                          \\"memory_days\\": config.MEMORY_RETENTION_DAYS,\\n                          \\"chain_max_gap_days\\": config.CHAIN_MAX_GAP_DAYS,\\n                          \\"chain_max_span_days\\": config.CHAIN_MAX_SPAN_DAYS},\\n        }\\n\\n    def identities(self, limit: int = 50) -> list[dict]:\\n        rows = self.store.query(\\n            \\"SELECT m.identity, m.first_seen, m.last_seen, m.risk, m.risk_updated, \\"\\n            \\"(SELECT COUNT(*) FROM findings f WHERE f.identity=m.identity) AS findings, \\"\\n            \\"(SELECT COUNT(*) FROM chain_hits h WHERE h.identity=m.identity) AS hits \\"\\n            \\"FROM identity_meta m\\")\\n        out = [{\\"identity\\": r[\\"identity\\"], \\"first_seen\\": r[\\"first_seen\\"], \\"last_seen\\": r[\\"last_seen\\"],\\n                \\"risk_peak\\": r[\\"risk\\"], \\"risk_now\\": self.current_risk(r[\\"risk\\"], r[\\"risk_updated\\"]),\\n                \\"findings\\": r[\\"findings\\"], \\"hits\\": r[\\"hits\\"]} for r in rows]\\n        out.sort(key=lambda x: (-x[\\"findings\\"], -x[\\"risk_peak\\"], x[\\"identity\\"]))\\n        return out[: max(1, min(int(limit), 1000))]\\n\\n    def findings(self, limit: int = 100, identity: str | None = None) -> list[dict]:\\n        sql = \\"SELECT * FROM findings\\"\\n        params: list = []\\n        if identity:\\n            sql += \\" WHERE identity=?\\"\\n            params.append(identity)\\n        sql += \\" ORDER BY risk DESC, last_time DESC LIMIT ?\\"\\n        params.append(max(1, min(int(limit), 1000)))\\n        return [self._finding_row(r) for r in self.store.query(sql, params)]\\n\\n    @staticmethod\\n    def _finding_row(r: sqlite3.Row) -> dict:\\n        return {\\"finding_id\\": r[\\"finding_id\\"], \\"identity\\": r[\\"identity\\"], \\"risk\\": r[\\"risk\\"],\\n                \\"stages\\": json.loads(r[\\"stages\\"]), \\"steps\\": json.loads(r[\\"steps\\"]),\\n                \\"evidence\\": json.loads(r[\\"evidence\\"]), \\"first_time\\": r[\\"first_time\\"], \\"last_time\\": r[\\"last_time\\"],\\n                \\"days_spanned\\": r[\\"days_spanned\\"], \\"status\\": r[\\"status\\"], \\"narrative\\": r[\\"narrative\\"],\\n                \\"updated\\": r[\\"updated\\"]}\\n\\n    def identity_view(self, identity: str, days: int = 30) -> dict | None:\\n        meta = self.store.one(\\"SELECT * FROM identity_meta WHERE identity=?\\", (identity,))\\n        if meta is None:\\n            return None\\n        days = max(1, min(int(days), 90))\\n        end = _day(self.data_clock() or meta[\\"last_seen\\"])\\n        start = end - timedelta(days=days - 1)\\n        daily = {r[\\"day\\"]: dict(r) for r in self.store.query(\\n            \\"SELECT * FROM identity_daily WHERE identity=? AND day BETWEEN ? AND ?\\",\\n            (identity, start.isoformat(), end.isoformat()))}\\n        hits = self.store.query(\\"SELECT kind, day, stage, severity, first_time, last_time, event_ids, detail \\"\\n                                \\"FROM chain_hits WHERE identity=? AND day BETWEEN ? AND ? ORDER BY first_time\\",\\n                                (identity, start.isoformat(), end.isoformat()))\\n        hits_by_day: dict[str, list[str]] = {}\\n        for h in hits:\\n            hits_by_day.setdefault(h[\\"day\\"], []).append(h[\\"kind\\"])\\n        series = []\\n        for i in range(days):\\n            d = (start + timedelta(days=i)).isoformat()\\n            row = daily.get(d, {})\\n            series.append({\\n                \\"day\\": d,\\n                \\"events\\": row.get(\\"events\\", 0), \\"logins\\": row.get(\\"logins\\", 0),\\n                \\"discovery\\": row.get(\\"discovery\\", 0), \\"data_reads\\": row.get(\\"data_reads\\", 0),\\n                \\"sensitive_reads\\": row.get(\\"sensitive_reads\\", 0), \\"writes\\": row.get(\\"writes\\", 0),\\n                \\"privesc\\": row.get(\\"privesc\\", 0), \\"credential\\": row.get(\\"credential\\", 0),\\n                \\"exfil\\": row.get(\\"exfil\\", 0), \\"evasion\\": row.get(\\"evasion\\", 0),\\n                \\"new_networks\\": row.get(\\"new_networks\\", 0), \\"max_risk\\": row.get(\\"max_risk\\", 0.0),\\n                \\"hits\\": hits_by_day.get(d, []),\\n            })\\n        return {\\n            \\"identity\\": identity,\\n            \\"first_seen\\": meta[\\"first_seen\\"], \\"last_seen\\": meta[\\"last_seen\\"],\\n            \\"risk_peak\\": meta[\\"risk\\"], \\"risk_now\\": self.current_risk(meta[\\"risk\\"], meta[\\"risk_updated\\"]),\\n            \\"window\\": {\\"start\\": start.isoformat(), \\"end\\": end.isoformat(), \\"days\\": days},\\n            \\"days\\": series,\\n            \\"hits\\": [{\\"kind\\": h[\\"kind\\"], \\"label\\": catalog.HIT_KINDS[h[\\"kind\\"]][2], \\"day\\": h[\\"day\\"],\\n                      \\"stage\\": h[\\"stage\\"], \\"severity\\": h[\\"severity\\"], \\"first_time\\": h[\\"first_time\\"],\\n                      \\"last_time\\": h[\\"last_time\\"], \\"event_ids\\": json.loads(h[\\"event_ids\\"]),\\n                      \\"detail\\": json.loads(h[\\"detail\\"] or \\"{}\\")} for h in hits],\\n            \\"findings\\": self.findings(identity=identity, limit=20),\\n        }\\n\\n    def evidence_events(self, event_ids: list[str]) -> list[dict]:\\n        ids = [str(e) for e in event_ids][:200]\\n        if not ids:\\n            return []\\n        rows = self.store.query(\\n            f\\"SELECT event_id, time, source, identity, action, category, ip, resource, outcome, raw FROM events \\"\\n            f\\"WHERE event_id IN ({\',\'.join(\'?\' * len(ids))}) ORDER BY time\\", ids)\\n        return [dict(r) for r in rows]\\n\\n    def reset(self) -> None:\\n        with self.store.tx() as c:\\n            for t in TABLES + (\\"meta\\",):\\n                c.execute(f\\"DELETE FROM {t}\\")\\n        self.store.checkpoint()\\n        self.store.vacuum()\\n\\n    def close(self) -> None:\\n        self.store.close()\\n", "app/memory30/normalize.py": "\\"\\"\\"Load Okta System Log / AWS CloudTrail JSON and normalize records into flat dicts. Pure functions.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport gzip\\nimport ipaddress\\nimport json\\nimport logging\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom typing import Any, Iterable\\n\\nfrom . import catalog, config\\n\\nlog = logging.getLogger(__name__)\\n\\nTIME_FMT = \\"%Y-%m-%dT%H:%M:%S.%fZ\\"\\n_EXTS = (\\".json\\", \\".jsonl\\", \\".ndjson\\", \\".json.gz\\", \\".jsonl.gz\\")\\n\\n\\n# ---------------------------------------------------------------- loading\\ndef _read_text(path: Path) -> str:\\n    if path.name.endswith(\\".gz\\"):\\n        with gzip.open(path, \\"rt\\", encoding=\\"utf-8\\") as fh:\\n            return fh.read()\\n    return path.read_text(encoding=\\"utf-8\\")\\n\\n\\ndef parse_json_text(text: str) -> list[dict]:\\n    \\"\\"\\"Accept a JSON list, {\\"Records\\": [...]}, a single event object, or JSON Lines.\\"\\"\\"\\n    text = text.strip()\\n    if not text:\\n        return []\\n    try:\\n        data = json.loads(text)\\n    except json.JSONDecodeError:\\n        out = []\\n        for line in text.splitlines():\\n            line = line.strip()\\n            if not line:\\n                continue\\n            try:\\n                obj = json.loads(line)\\n            except json.JSONDecodeError:\\n                continue\\n            out.extend(_unwrap(obj))\\n        return out\\n    return _unwrap(data)\\n\\n\\ndef _unwrap(data: Any) -> list[dict]:\\n    if isinstance(data, list):\\n        return [d for d in data if isinstance(d, dict)]\\n    if isinstance(data, dict):\\n        for key in (\\"Records\\", \\"records\\", \\"events\\", \\"data\\"):\\n            if isinstance(data.get(key), list):\\n                return [d for d in data[key] if isinstance(d, dict)]\\n        return [data]\\n    return []\\n\\n\\ndef iter_files(paths: Iterable[Path | str]) -> list[Path]:\\n    files: list[Path] = []\\n    for p in paths:\\n        p = Path(p)\\n        if p.is_file() and p.name.endswith(_EXTS):\\n            files.append(p)\\n        elif p.is_dir():\\n            files.extend(sorted(f for f in p.rglob(\\"*\\") if f.is_file() and f.name.endswith(_EXTS)))\\n    return files\\n\\n\\ndef load_paths(paths: Iterable[Path | str]) -> tuple[list[dict], dict]:\\n    records: list[dict] = []\\n    info = {\\"files\\": 0, \\"bad_files\\": 0}\\n    for f in iter_files(paths):\\n        try:\\n            records.extend(parse_json_text(_read_text(f)))\\n            info[\\"files\\"] += 1\\n        except (OSError, UnicodeDecodeError) as exc:\\n            info[\\"bad_files\\"] += 1\\n            log.warning(\\"memory30: cannot read %s: %s\\", f, exc.__class__.__name__)\\n    return records, info\\n\\n\\n# ---------------------------------------------------------------- helpers\\ndef parse_time(value: Any) -> datetime | None:\\n    if value is None:\\n        return None\\n    if isinstance(value, (int, float)):\\n        try:\\n            ts = value / 1000 if value > 1e11 else value\\n            return datetime.fromtimestamp(ts, tz=timezone.utc)\\n        except (OverflowError, OSError, ValueError):\\n            return None\\n    s = str(value).strip()\\n    if not s:\\n        return None\\n    if s.endswith(\\"Z\\"):\\n        s = s[:-1] + \\"+00:00\\"\\n    try:\\n        dt = datetime.fromisoformat(s)\\n    except ValueError:\\n        return None\\n    if dt.tzinfo is None:\\n        dt = dt.replace(tzinfo=timezone.utc)\\n    return dt.astimezone(timezone.utc)\\n\\n\\ndef fmt_time(dt: datetime) -> str:\\n    return dt.astimezone(timezone.utc).strftime(TIME_FMT)\\n\\n\\ndef network_of(ip: str | None) -> str | None:\\n    \\"\\"\\"Coarse network key: /16 for IPv4, /48 for IPv6. None for service names or invalid values.\\"\\"\\"\\n    if not ip:\\n        return None\\n    try:\\n        addr = ipaddress.ip_address(str(ip).strip())\\n    except ValueError:\\n        return None\\n    if addr.is_loopback or addr.is_link_local:\\n        return None\\n    if addr.version == 4:\\n        return \\"v4:\\" + str(ipaddress.ip_network(f\\"{addr}/16\\", strict=False).network_address)\\n    return \\"v6:\\" + str(ipaddress.ip_network(f\\"{addr}/48\\", strict=False).network_address)\\n\\n\\ndef is_sensitive(resource: str | None) -> bool:\\n    if not resource:\\n        return False\\n    low = resource.lower()\\n    return any(m in low for m in config.SENSITIVE_MARKERS)\\n\\n\\ndef _g(d: Any, *keys: str) -> Any:\\n    for k in keys:\\n        if not isinstance(d, dict):\\n            return None\\n        d = d.get(k)\\n    return d\\n\\n\\ndef _clip(raw: dict) -> str:\\n    try:\\n        s = json.dumps(raw, separators=(\\",\\", \\":\\"), default=str)\\n    except (TypeError, ValueError):\\n        s = \\"{}\\"\\n    return s[: config.RAW_MAX_CHARS]\\n\\n\\ndef detect_source(r: dict) -> str | None:\\n    if \\"eventType\\" in r and (\\"actor\\" in r or \\"uuid\\" in r):\\n        return \\"okta\\"\\n    if \\"eventName\\" in r and (\\"userIdentity\\" in r or \\"eventSource\\" in r):\\n        return \\"cloudtrail\\"\\n    return None\\n\\n\\n# ---------------------------------------------------------------- identity resolution\\ndef cloudtrail_identity(ui: dict | None) -> tuple[str, str | None]:\\n    \\"\\"\\"Return (identity, session_name). SAML/SSO sessions named after an email resolve to that email.\\"\\"\\"\\n    ui = ui or {}\\n    typ = ui.get(\\"type\\") or \\"\\"\\n    arn = ui.get(\\"arn\\") or \\"\\"\\n    session_name = None\\n    if typ in (\\"AssumedRole\\", \\"FederatedUser\\") or \\":assumed-role/\\" in arn:\\n        parts = arn.split(\\"/\\")\\n        role = parts[1] if len(parts) > 2 else (_g(ui, \\"sessionContext\\", \\"sessionIssuer\\", \\"userName\\") or \\"role\\")\\n        session_name = parts[-1] if len(parts) > 2 else None\\n        if not session_name and ui.get(\\"principalId\\") and \\":\\" in str(ui[\\"principalId\\"]):\\n            session_name = str(ui[\\"principalId\\"]).split(\\":\\", 1)[1]\\n        src_identity = _g(ui, \\"sessionContext\\", \\"sourceIdentity\\") or ui.get(\\"sourceIdentity\\")\\n        if src_identity:\\n            return str(src_identity).lower(), session_name\\n        if session_name and \\"@\\" in session_name:\\n            return session_name.lower(), session_name\\n        return f\\"{role}/{session_name}\\" if session_name else str(role), session_name\\n    if typ == \\"Root\\":\\n        return \\"root\\", None\\n    if ui.get(\\"userName\\"):\\n        return str(ui[\\"userName\\"]).lower() if \\"@\\" in str(ui[\\"userName\\"]) else str(ui[\\"userName\\"]), None\\n    if arn:\\n        return arn.split(\\"/\\")[-1] or arn, None\\n    return str(ui.get(\\"principalId\\") or \\"unknown\\"), None\\n\\n\\n_CT_RESOURCE_KEYS = (\\"bucketName\\", \\"secretId\\", \\"keyId\\", \\"snapshotId\\", \\"dBSnapshotIdentifier\\", \\"functionName\\",\\n                     \\"roleName\\", \\"userName\\", \\"policyArn\\", \\"groupName\\", \\"name\\", \\"trailName\\", \\"detectorId\\",\\n                     \\"logGroupName\\", \\"instanceId\\", \\"repositoryName\\", \\"tableName\\")\\n\\n\\ndef cloudtrail_resource(r: dict) -> str | None:\\n    rp = r.get(\\"requestParameters\\") if isinstance(r.get(\\"requestParameters\\"), dict) else {}\\n    bucket = rp.get(\\"bucketName\\")\\n    key = rp.get(\\"key\\")\\n    if bucket:\\n        return f\\"{bucket}/{key}\\" if key else str(bucket)\\n    for k in _CT_RESOURCE_KEYS:\\n        if rp.get(k):\\n            return str(rp[k])\\n    res = r.get(\\"resources\\")\\n    if isinstance(res, list) and res and isinstance(res[0], dict):\\n        return res[0].get(\\"ARN\\") or res[0].get(\\"arn\\")\\n    return None\\n\\n\\n# ---------------------------------------------------------------- normalize\\ndef normalize(r: dict) -> dict | None:\\n    \\"\\"\\"Return a flat event dict or None if the record is not usable.\\"\\"\\"\\n    if not isinstance(r, dict):\\n        return None\\n    src = detect_source(r)\\n    if src == \\"okta\\":\\n        return _normalize_okta(r)\\n    if src == \\"cloudtrail\\":\\n        return _normalize_cloudtrail(r)\\n    return None\\n\\n\\ndef _base(event_id: str, dt: datetime, source: str, identity: str, action: str, outcome: str) -> dict:\\n    return {\\n        \\"event_id\\": f\\"{source}:{event_id}\\",\\n        \\"time\\": fmt_time(dt),\\n        \\"day\\": dt.strftime(\\"%Y-%m-%d\\"),\\n        \\"source\\": source,\\n        \\"identity\\": identity,\\n        \\"action\\": action,\\n        \\"outcome\\": outcome,\\n    }\\n\\n\\ndef _normalize_okta(r: dict) -> dict | None:\\n    eid = r.get(\\"uuid\\") or r.get(\\"id\\")\\n    dt = parse_time(r.get(\\"published\\"))\\n    actor = r.get(\\"actor\\") or {}\\n    identity = (actor.get(\\"alternateId\\") or actor.get(\\"id\\") or \\"\\").strip()\\n    action = r.get(\\"eventType\\") or \\"\\"\\n    if not eid or not dt or not identity or not action:\\n        return None\\n    identity = identity.lower()\\n    res = str(_g(r, \\"outcome\\", \\"result\\") or \\"\\").upper()\\n    outcome = \\"success\\" if res in (\\"SUCCESS\\", \\"ALLOW\\") else \\"failure\\" if res in (\\"FAILURE\\", \\"DENY\\") else \\"unknown\\"\\n    ip = _g(r, \\"client\\", \\"ipAddress\\")\\n    target = r.get(\\"target\\") if isinstance(r.get(\\"target\\"), list) else []\\n    resource = None\\n    if target and isinstance(target[0], dict):\\n        resource = target[0].get(\\"alternateId\\") or target[0].get(\\"displayName\\")\\n    n = _base(str(eid), dt, \\"okta\\", identity, action, outcome)\\n    asn = _g(r, \\"securityContext\\", \\"asNumber\\")\\n    n.update({\\n        \\"service\\": \\"okta\\",\\n        \\"ip\\": ip,\\n        \\"net\\": f\\"asn:{asn}\\" if asn else network_of(ip),\\n        \\"country\\": _g(r, \\"client\\", \\"geographicalContext\\", \\"country\\"),\\n        \\"is_proxy\\": bool(_g(r, \\"securityContext\\", \\"isProxy\\")),\\n        \\"resource\\": resource,\\n        \\"read_only\\": True,\\n        \\"session\\": _g(r, \\"authenticationContext\\", \\"externalSessionId\\"),\\n        \\"raw\\": _clip(r),\\n    })\\n    n[\\"category\\"] = catalog.categorize(\\"okta\\", action, outcome)\\n    n[\\"sensitive\\"] = is_sensitive(resource)\\n    return n\\n\\n\\ndef _normalize_cloudtrail(r: dict) -> dict | None:\\n    eid = r.get(\\"eventID\\")\\n    dt = parse_time(r.get(\\"eventTime\\"))\\n    action = r.get(\\"eventName\\") or \\"\\"\\n    if not eid or not dt or not action:\\n        return None\\n    identity, session_name = cloudtrail_identity(r.get(\\"userIdentity\\"))\\n    outcome = \\"failure\\" if r.get(\\"errorCode\\") else \\"success\\"\\n    ip = r.get(\\"sourceIPAddress\\")\\n    resource = cloudtrail_resource(r)\\n    read_only = r.get(\\"readOnly\\")\\n    if read_only is None:\\n        read_only = action.startswith((\\"Get\\", \\"List\\", \\"Describe\\", \\"Head\\", \\"Lookup\\"))\\n    n = _base(str(eid), dt, \\"cloudtrail\\", identity, action, outcome)\\n    n.update({\\n        \\"service\\": str(r.get(\\"eventSource\\") or \\"\\").split(\\".\\")[0] or \\"aws\\",\\n        \\"ip\\": ip,\\n        \\"net\\": network_of(ip),\\n        \\"country\\": None,\\n        \\"is_proxy\\": False,\\n        \\"resource\\": resource,\\n        \\"read_only\\": bool(read_only),\\n        \\"session\\": session_name,\\n        \\"raw\\": _clip(r),\\n    })\\n    n[\\"category\\"] = catalog.categorize(\\"cloudtrail\\", action, outcome)\\n    n[\\"sensitive\\"] = is_sensitive(resource)\\n    return n\\n", "app/memory30/store.py": "\\"\\"\\"SQLite storage for the 30-day memory (WAL mode, parameterized queries, one lock for thread safety).\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport sqlite3\\nimport threading\\nfrom contextlib import contextmanager\\nfrom pathlib import Path\\nfrom typing import Any, Iterator\\n\\nSCHEMA = \\"\\"\\"\\nCREATE TABLE IF NOT EXISTS events (\\n    event_id   TEXT PRIMARY KEY,\\n    time       TEXT NOT NULL,\\n    day        TEXT NOT NULL,\\n    source     TEXT NOT NULL,\\n    identity   TEXT NOT NULL,\\n    action     TEXT NOT NULL,\\n    category   TEXT NOT NULL,\\n    service    TEXT,\\n    outcome    TEXT,\\n    ip         TEXT,\\n    net        TEXT,\\n    country    TEXT,\\n    is_proxy   INTEGER NOT NULL DEFAULT 0,\\n    resource   TEXT,\\n    sensitive  INTEGER NOT NULL DEFAULT 0,\\n    read_only  INTEGER NOT NULL DEFAULT 1,\\n    session    TEXT,\\n    evidence   INTEGER NOT NULL DEFAULT 0,\\n    raw        TEXT\\n);\\nCREATE INDEX IF NOT EXISTS ix_events_identity_time ON events(identity, time);\\nCREATE INDEX IF NOT EXISTS ix_events_time ON events(time);\\nCREATE INDEX IF NOT EXISTS ix_events_identity_day_cat ON events(identity, day, category);\\n\\nCREATE TABLE IF NOT EXISTS identity_daily (\\n    identity         TEXT NOT NULL,\\n    day              TEXT NOT NULL,\\n    events           INTEGER NOT NULL DEFAULT 0,\\n    logins           INTEGER NOT NULL DEFAULT 0,\\n    login_failures   INTEGER NOT NULL DEFAULT 0,\\n    discovery        INTEGER NOT NULL DEFAULT 0,\\n    data_reads       INTEGER NOT NULL DEFAULT 0,\\n    sensitive_reads  INTEGER NOT NULL DEFAULT 0,\\n    writes           INTEGER NOT NULL DEFAULT 0,\\n    privesc          INTEGER NOT NULL DEFAULT 0,\\n    credential       INTEGER NOT NULL DEFAULT 0,\\n    exfil            INTEGER NOT NULL DEFAULT 0,\\n    evasion          INTEGER NOT NULL DEFAULT 0,\\n    new_networks     INTEGER NOT NULL DEFAULT 0,\\n    max_risk         REAL NOT NULL DEFAULT 0,\\n    PRIMARY KEY (identity, day)\\n);\\n\\nCREATE TABLE IF NOT EXISTS daily_services (\\n    identity TEXT NOT NULL,\\n    day      TEXT NOT NULL,\\n    service  TEXT NOT NULL,\\n    PRIMARY KEY (identity, day, service)\\n);\\n\\nCREATE TABLE IF NOT EXISTS identity_meta (\\n    identity     TEXT PRIMARY KEY,\\n    first_seen   TEXT NOT NULL,\\n    last_seen    TEXT NOT NULL,\\n    risk         REAL NOT NULL DEFAULT 0,\\n    risk_updated TEXT\\n);\\n\\nCREATE TABLE IF NOT EXISTS identity_networks (\\n    identity   TEXT NOT NULL,\\n    net        TEXT NOT NULL,\\n    first_seen TEXT NOT NULL,\\n    last_seen  TEXT NOT NULL,\\n    count      INTEGER NOT NULL DEFAULT 0,\\n    PRIMARY KEY (identity, net)\\n);\\n\\nCREATE TABLE IF NOT EXISTS identity_write_targets (\\n    identity   TEXT NOT NULL,\\n    target     TEXT NOT NULL,\\n    first_seen TEXT NOT NULL,\\n    last_seen  TEXT NOT NULL,\\n    count      INTEGER NOT NULL DEFAULT 0,\\n    PRIMARY KEY (identity, target)\\n);\\n\\nCREATE TABLE IF NOT EXISTS chain_hits (\\n    identity   TEXT NOT NULL,\\n    kind       TEXT NOT NULL,\\n    day        TEXT NOT NULL,\\n    stage      TEXT NOT NULL,\\n    severity   REAL NOT NULL,\\n    first_time TEXT NOT NULL,\\n    last_time  TEXT NOT NULL,\\n    event_ids  TEXT NOT NULL,\\n    detail     TEXT,\\n    PRIMARY KEY (identity, kind, day)\\n);\\nCREATE INDEX IF NOT EXISTS ix_hits_identity_time ON chain_hits(identity, first_time);\\n\\nCREATE TABLE IF NOT EXISTS findings (\\n    finding_id   TEXT PRIMARY KEY,\\n    identity     TEXT NOT NULL,\\n    risk         REAL NOT NULL,\\n    stages       TEXT NOT NULL,\\n    steps        TEXT NOT NULL,\\n    evidence     TEXT NOT NULL,\\n    first_time   TEXT NOT NULL,\\n    last_time    TEXT NOT NULL,\\n    days_spanned INTEGER NOT NULL,\\n    status       TEXT NOT NULL DEFAULT \'open\',\\n    narrative    TEXT NOT NULL,\\n    updated      TEXT NOT NULL\\n);\\nCREATE INDEX IF NOT EXISTS ix_findings_identity ON findings(identity);\\n\\nCREATE TABLE IF NOT EXISTS meta (\\n    key   TEXT PRIMARY KEY,\\n    value TEXT\\n);\\n\\"\\"\\"\\n\\nTABLES = (\\"events\\", \\"identity_daily\\", \\"daily_services\\", \\"identity_meta\\", \\"identity_networks\\",\\n          \\"identity_write_targets\\", \\"chain_hits\\", \\"findings\\")\\n\\n\\nclass Store:\\n    def __init__(self, path: Path | str):\\n        self.path = Path(path)\\n        if str(self.path) != \\":memory:\\":\\n            self.path.parent.mkdir(parents=True, exist_ok=True)\\n        self._lock = threading.RLock()\\n        self.conn = sqlite3.connect(str(self.path), check_same_thread=False, isolation_level=None)\\n        self.conn.row_factory = sqlite3.Row\\n        with self._lock:\\n            self.conn.execute(\\"PRAGMA journal_mode=WAL\\")\\n            self.conn.execute(\\"PRAGMA synchronous=NORMAL\\")\\n            self.conn.execute(\\"PRAGMA foreign_keys=ON\\")\\n            self.conn.executescript(SCHEMA)\\n\\n    # ---------------------------------------------------------------- basics\\n    @contextmanager\\n    def tx(self) -> Iterator[sqlite3.Connection]:\\n        with self._lock:\\n            self.conn.execute(\\"BEGIN IMMEDIATE\\")\\n            try:\\n                yield self.conn\\n            except BaseException:\\n                self.conn.execute(\\"ROLLBACK\\")\\n                raise\\n            else:\\n                self.conn.execute(\\"COMMIT\\")\\n\\n    def query(self, sql: str, params: tuple | list = ()) -> list[sqlite3.Row]:\\n        with self._lock:\\n            return self.conn.execute(sql, params).fetchall()\\n\\n    def one(self, sql: str, params: tuple | list = ()) -> sqlite3.Row | None:\\n        with self._lock:\\n            return self.conn.execute(sql, params).fetchone()\\n\\n    def execute(self, sql: str, params: tuple | list = ()) -> int:\\n        with self._lock:\\n            return self.conn.execute(sql, params).rowcount\\n\\n    def get_meta(self, key: str, default: Any = None) -> Any:\\n        row = self.one(\\"SELECT value FROM meta WHERE key=?\\", (key,))\\n        return row[\\"value\\"] if row else default\\n\\n    def set_meta(self, key: str, value: str) -> None:\\n        self.execute(\\"INSERT INTO meta(key, value) VALUES(?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value\\",\\n                     (key, value))\\n\\n    def vacuum(self) -> None:\\n        with self._lock:\\n            self.conn.execute(\\"VACUUM\\")\\n\\n    def checkpoint(self) -> None:\\n        with self._lock:\\n            self.conn.execute(\\"PRAGMA wal_checkpoint(TRUNCATE)\\")\\n\\n    def size_bytes(self) -> int:\\n        total = 0\\n        for suffix in (\\"\\", \\"-wal\\", \\"-shm\\"):\\n            p = Path(str(self.path) + suffix)\\n            if p.exists():\\n                total += p.stat().st_size\\n        return total\\n\\n    def close(self) -> None:\\n        with self._lock:\\n            try:\\n                self.conn.close()\\n            except sqlite3.Error:\\n                pass\\n", "app/memory30/synth.py": "\\"\\"\\"Synthetic 30-day Okta + CloudTrail data with hidden slow attacks and ground-truth labels.\\n\\nSYNTHETIC DATA: used only to test long-range memory. Never use it for the official KPIs.\\nScenarios (inserted when the period is long enough):\\n  slow_escalation   (needs >= 19 days)  proxy login -> new access key -> discovery burst -> admin policy, 14 days\\n  slow_heist        (needs >= 22 days)  VPN session + MFA device attempt -> 12 days of discovery -> prod JS change\\n  insider_staircase (needs >= 29 days)  finance reads growing weekly for 4 weeks -> snapshot shared externally\\n  gap_31_days       (needs >= 34 days)  two risky steps 32 days apart: must NOT be linked\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport json\\nimport random\\nimport uuid\\nfrom datetime import date, datetime, timedelta, timezone\\nfrom pathlib import Path\\n\\nACCOUNT = \\"111122223333\\"\\nEXTERNAL_ACCOUNT = \\"999988887777\\"\\nTEAMS = [\\"engineering\\", \\"finance\\", \\"sales\\", \\"ops\\", \\"data\\"]\\nOFFICE_ASN = 64500\\nPROXY_IP, PROXY_ASN = \\"185.220.101.23\\", 64510\\nVPN_IP = \\"45.137.21.9\\"\\n\\n\\nclass _Gen:\\n    def __init__(self, seed: int):\\n        self.rng = random.Random(seed)\\n        self.okta: list[dict] = []\\n        self.ct: list[dict] = []\\n\\n    def _uuid(self) -> str:\\n        return str(uuid.UUID(int=self.rng.getrandbits(128), version=4))\\n\\n    @staticmethod\\n    def _ts(dt: datetime) -> str:\\n        return dt.strftime(\\"%Y-%m-%dT%H:%M:%S.\\") + f\\"{dt.microsecond // 1000:03d}Z\\"\\n\\n    def okta_login(self, email: str, dt: datetime, ip: str, asn: int, country: str, city: str,\\n                   proxy: bool = False, event_type: str = \\"user.session.start\\", result: str = \\"SUCCESS\\") -> str:\\n        eid = self._uuid()\\n        self.okta.append({\\n            \\"uuid\\": eid, \\"published\\": self._ts(dt), \\"eventType\\": event_type,\\n            \\"displayMessage\\": \\"User login to Okta\\",\\n            \\"actor\\": {\\"id\\": \\"00u\\" + email.split(\\"@\\")[0].replace(\\".\\", \\"\\")[:12], \\"type\\": \\"User\\", \\"alternateId\\": email},\\n            \\"client\\": {\\"ipAddress\\": ip, \\"userAgent\\": {\\"rawUserAgent\\": \\"Mozilla/5.0\\", \\"os\\": \\"Windows\\",\\n                                                      \\"browser\\": \\"CHROME\\"},\\n                       \\"geographicalContext\\": {\\"country\\": country, \\"city\\": city}},\\n            \\"securityContext\\": {\\"asNumber\\": asn, \\"asOrg\\": \\"AS\\" + str(asn), \\"isProxy\\": proxy},\\n            \\"authenticationContext\\": {\\"externalSessionId\\": \\"idx\\" + eid[:12]},\\n            \\"outcome\\": {\\"result\\": result},\\n        })\\n        return f\\"okta:{eid}\\"\\n\\n    def ct_event(self, email: str, team: str, dt: datetime, name: str, source: str, ip: str,\\n                 params: dict | None = None, error: str | None = None, saml: bool = False) -> str:\\n        eid = self._uuid()\\n        if saml:\\n            ui = {\\"type\\": \\"SAMLUser\\", \\"principalId\\": f\\"okta:{email}\\", \\"userName\\": email}\\n        else:\\n            ui = {\\"type\\": \\"AssumedRole\\", \\"principalId\\": f\\"AROAEXAMPLE{team.upper()}:{email}\\",\\n                  \\"arn\\": f\\"arn:aws:sts::{ACCOUNT}:assumed-role/{team}-role/{email}\\",\\n                  \\"accountId\\": ACCOUNT, \\"accessKeyId\\": \\"ASIA\\" + eid.replace(\\"-\\", \\"\\")[:16].upper(),\\n                  \\"sessionContext\\": {\\"sessionIssuer\\": {\\"type\\": \\"Role\\", \\"userName\\": f\\"{team}-role\\",\\n                                                       \\"arn\\": f\\"arn:aws:iam::{ACCOUNT}:role/{team}-role\\"}}}\\n        rec = {\\n            \\"eventVersion\\": \\"1.09\\", \\"eventID\\": eid, \\"eventTime\\": self._ts(dt).split(\\".\\")[0] + \\"Z\\",\\n            \\"eventSource\\": f\\"{source}.amazonaws.com\\", \\"eventName\\": name, \\"awsRegion\\": \\"ap-south-1\\",\\n            \\"sourceIPAddress\\": ip, \\"userAgent\\": \\"aws-cli/2.15.0\\", \\"userIdentity\\": ui,\\n            \\"requestParameters\\": params or {}, \\"recipientAccountId\\": ACCOUNT,\\n            \\"readOnly\\": name.startswith((\\"Get\\", \\"List\\", \\"Describe\\")),\\n            \\"managementEvent\\": source not in (\\"s3\\",) or name not in (\\"GetObject\\", \\"PutObject\\"),\\n        }\\n        if error:\\n            rec[\\"errorCode\\"] = error\\n            rec[\\"errorMessage\\"] = \\"User is not authorized to perform this operation\\"\\n        self.ct.append(rec)\\n        return f\\"cloudtrail:{eid}\\"\\n\\n\\ndef _profiles(n: int, rng: random.Random) -> list[dict]:\\n    first = [\\"arun\\", \\"divya\\", \\"kiran\\", \\"neha\\", \\"rahul\\", \\"sneha\\", \\"vikram\\", \\"pooja\\", \\"anil\\", \\"isha\\", \\"manoj\\", \\"priya\\"]\\n    out = []\\n    for i in range(n):\\n        team = TEAMS[i % len(TEAMS)]\\n        name = f\\"{first[i % len(first)]}{i:03d}\\"\\n        out.append({\\n            \\"email\\": f\\"{name}@acme.example\\", \\"team\\": team,\\n            \\"office_ip\\": f\\"198.51.100.{(i % 250) + 1}\\",\\n            \\"home_ip\\": f\\"203.0.{113 + (i % 10)}.{(i * 7) % 250 + 1}\\", \\"home_asn\\": 64501 + (i % 5),\\n            \\"home_ratio\\": rng.choice([0.0, 0.1, 0.2, 0.3]),\\n            \\"start_hour\\": rng.choice([3, 4, 5]),  # UTC (about 08:30-10:30 IST)\\n        })\\n    for email in (\\"ravi.dev@acme.example\\", \\"safe.dev@acme.example\\", \\"meera.ops@acme.example\\",\\n                  \\"old.ops@acme.example\\"):\\n        out.append({\\"email\\": email, \\"team\\": \\"engineering\\", \\"office_ip\\": \\"198.51.100.200\\",\\n                    \\"home_ip\\": \\"203.0.120.77\\", \\"home_asn\\": 64503, \\"home_ratio\\": 0.0, \\"start_hour\\": 4})\\n    return out\\n\\n\\ndef _normal_day(g: _Gen, p: dict, day: date) -> None:\\n    rng = g.rng\\n    at_home = rng.random() < p[\\"home_ratio\\"]\\n    ip = p[\\"home_ip\\"] if at_home else p[\\"office_ip\\"]\\n    asn = p[\\"home_asn\\"] if at_home else OFFICE_ASN\\n    t = datetime(day.year, day.month, day.day, p[\\"start_hour\\"], rng.randint(0, 59), rng.randint(0, 59),\\n                 tzinfo=timezone.utc)\\n    g.okta_login(p[\\"email\\"], t, ip, asn, \\"India\\", \\"Bengaluru\\")\\n    t += timedelta(seconds=rng.randint(20, 90))\\n    g.ct_event(p[\\"email\\"], p[\\"team\\"], t, \\"AssumeRoleWithSAML\\", \\"sts\\", ip,\\n               {\\"roleArn\\": f\\"arn:aws:iam::{ACCOUNT}:role/{p[\'team\']}-role\\"}, saml=True)\\n    team = p[\\"team\\"]\\n    for _ in range(rng.randint(4, 12)):\\n        t += timedelta(minutes=rng.randint(3, 40))\\n        r = rng.random()\\n        if team == \\"finance\\" and r < 0.45:\\n            g.ct_event(p[\\"email\\"], team, t, \\"GetObject\\", \\"s3\\", ip,\\n                       {\\"bucketName\\": \\"acme-finance-reports\\", \\"key\\": f\\"q3/report-{rng.randint(1, 40)}.xlsx\\"})\\n        elif r < 0.65:\\n            g.ct_event(p[\\"email\\"], team, t, \\"GetObject\\", \\"s3\\", ip,\\n                       {\\"bucketName\\": f\\"acme-{team}-shared\\", \\"key\\": f\\"docs/file-{rng.randint(1, 200)}.pdf\\"})\\n        elif r < 0.82:\\n            g.ct_event(p[\\"email\\"], team, t, \\"PutObject\\", \\"s3\\", ip,\\n                       {\\"bucketName\\": f\\"acme-{team}-shared\\", \\"key\\": f\\"docs/file-{rng.randint(1, 200)}.pdf\\"})\\n        elif r < 0.90:\\n            g.ct_event(p[\\"email\\"], team, t, \\"ListBuckets\\", \\"s3\\", ip)\\n        elif team == \\"engineering\\" and r < 0.97:\\n            g.ct_event(p[\\"email\\"], team, t, \\"DescribeInstances\\", \\"ec2\\", ip)\\n        else:\\n            g.ct_event(p[\\"email\\"], team, t, \\"GetCallerIdentity\\", \\"sts\\", ip)\\n\\n\\ndef generate(days: int = 30, identities: int = 50, seed: int = 42, end: date | None = None) -> tuple[list, list, dict]:\\n    days = max(7, min(int(days), 120))\\n    g = _Gen(seed)\\n    end = end or datetime.now(timezone.utc).date()\\n    start = end - timedelta(days=days - 1)\\n    profiles = _profiles(max(5, int(identities)), g.rng)\\n    by_email = {p[\\"email\\"]: p for p in profiles}\\n    labels: dict = {\\"synthetic\\": True, \\"start\\": start.isoformat(), \\"end\\": end.isoformat(), \\"days\\": days,\\n                    \\"identities\\": len(profiles), \\"scenarios\\": []}\\n\\n    for i in range(days):\\n        day = start + timedelta(days=i)\\n        weekend = day.weekday() >= 5\\n        for p in profiles:\\n            forced = p[\\"email\\"] == \\"meera.ops@acme.example\\" and i == days - 1\\n            if forced or g.rng.random() < (0.15 if weekend else 0.9):\\n                _normal_day(g, p, day)\\n\\n    def at(day_index: int, hour: int, minute: int = 0) -> datetime:\\n        d = start + timedelta(days=day_index)\\n        return datetime(d.year, d.month, d.day, hour, minute, tzinfo=timezone.utc)\\n\\n    # ---- 1. slow escalation over 14 days\\n    if days >= 19:\\n        p = by_email[\\"ravi.dev@acme.example\\"]\\n        d0 = days - 16\\n        ids = [g.okta_login(p[\\"email\\"], at(d0, 21, 5), PROXY_IP, PROXY_ASN, \\"Netherlands\\", \\"Amsterdam\\", proxy=True)]\\n        ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(d0, 21, 9), \\"ListBuckets\\", \\"s3\\", PROXY_IP))\\n        ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(d0 + 5, 22, 0), \\"CreateAccessKey\\", \\"iam\\", PROXY_IP,\\n                              {\\"userName\\": \\"ravi.dev\\"}))\\n        for k, (name, src) in enumerate([(\\"ListUsers\\", \\"iam\\"), (\\"ListRoles\\", \\"iam\\"), (\\"ListPolicies\\", \\"iam\\"),\\n                                         (\\"GetAccountAuthorizationDetails\\", \\"iam\\"), (\\"ListBuckets\\", \\"s3\\"),\\n                                         (\\"DescribeInstances\\", \\"ec2\\"), (\\"ListSecrets\\", \\"secretsmanager\\")]):\\n            ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(d0 + 9, 22, k * 3), name, src, PROXY_IP))\\n        ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(d0 + 14, 22, 30), \\"AttachUserPolicy\\", \\"iam\\", PROXY_IP,\\n                              {\\"userName\\": \\"ravi.dev\\",\\n                               \\"policyArn\\": \\"arn:aws:iam::aws:policy/AdministratorAccess\\"}))\\n        ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(d0 + 14, 22, 41), \\"GetSecretValue\\", \\"secretsmanager\\",\\n                              PROXY_IP, {\\"secretId\\": \\"acme/prod/db-password\\"}))\\n        labels[\\"scenarios\\"].append({\\"name\\": \\"slow_escalation\\", \\"identity\\": p[\\"email\\"], \\"days\\": 15,\\n                                    \\"expected\\": \\"linked\\", \\"min_stages\\": 3, \\"event_ids\\": ids})\\n\\n    # ---- 2. slow heist (Bybit-style, inspired by the public timeline)\\n    if days >= 22:\\n        p = by_email[\\"safe.dev@acme.example\\"]\\n        b0 = days - 19\\n        ids = [g.ct_event(p[\\"email\\"], \\"engineering\\", at(b0, 20, 0), \\"GetCallerIdentity\\", \\"sts\\", VPN_IP),\\n               g.ct_event(p[\\"email\\"], \\"engineering\\", at(b0, 20, 4), \\"CreateVirtualMFADevice\\", \\"iam\\", VPN_IP,\\n                          {\\"virtualMFADeviceName\\": \\"backup-device\\"}, error=\\"AccessDenied\\")]\\n        recon = [(\\"ListRoles\\", \\"iam\\", {}), (\\"ListBuckets\\", \\"s3\\", {}),\\n                 (\\"GetBucketPolicy\\", \\"s3\\", {\\"bucketName\\": \\"acme-prod-webapp\\"}),\\n                 (\\"ListDistributions\\", \\"cloudfront\\", {}), (\\"DescribeInstances\\", \\"ec2\\", {}),\\n                 (\\"ListFunctions\\", \\"lambda\\", {})]\\n        for day_off in range(1, 13):\\n            for k, (name, src, prm) in enumerate(recon):\\n                ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(b0 + day_off, 20, 10 + k * 4), name, src,\\n                                      VPN_IP, prm))\\n        ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(b0 + 14, 20, 30), \\"GetObject\\", \\"s3\\", VPN_IP,\\n                              {\\"bucketName\\": \\"acme-prod-webapp\\", \\"key\\": \\"static/js/app.js\\"}))\\n        ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(b0 + 15, 20, 45), \\"PutObject\\", \\"s3\\", VPN_IP,\\n                              {\\"bucketName\\": \\"acme-prod-webapp\\", \\"key\\": \\"static/js/app.js\\"}))\\n        labels[\\"scenarios\\"].append({\\"name\\": \\"slow_heist\\", \\"identity\\": p[\\"email\\"], \\"days\\": 16,\\n                                    \\"expected\\": \\"linked\\", \\"min_stages\\": 3, \\"event_ids\\": ids})\\n\\n    # ---- 3. insider staircase (real employee, usual place and time)\\n    if days >= 29:\\n        p = by_email[\\"meera.ops@acme.example\\"]\\n        s0 = days - 28\\n        per_day = [2, 4, 7, 13]\\n        ids = []\\n        for w in range(4):\\n            for dd in range(7):\\n                di = s0 + w * 7 + dd\\n                if di >= days or (start + timedelta(days=di)).weekday() >= 5 and di != days - 1:\\n                    continue\\n                for k in range(per_day[w]):\\n                    ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(di, 11, 2 + k * 3), \\"GetObject\\", \\"s3\\",\\n                                          p[\\"office_ip\\"], {\\"bucketName\\": \\"acme-finance-ledger\\",\\n                                                           \\"key\\": f\\"ledger/2026/part-{w}-{dd}-{k}.csv\\"}))\\n        ids.append(g.ct_event(p[\\"email\\"], \\"engineering\\", at(days - 1, 12, 30), \\"ModifySnapshotAttribute\\", \\"ec2\\",\\n                              p[\\"office_ip\\"], {\\"snapshotId\\": \\"snap-finance-db-0423\\",\\n                                               \\"attributeType\\": \\"CREATE_VOLUME_PERMISSION\\",\\n                                               \\"createVolumePermission\\": {\\"add\\": {\\"items\\": [\\n                                                   {\\"userId\\": EXTERNAL_ACCOUNT}]}}}))\\n        labels[\\"scenarios\\"].append({\\"name\\": \\"insider_staircase\\", \\"identity\\": p[\\"email\\"], \\"days\\": 28,\\n                                    \\"expected\\": \\"linked\\", \\"min_stages\\": 2, \\"event_ids\\": ids})\\n\\n    # ---- 4. two risky steps 32 days apart: must NOT be linked\\n    if days >= 34:\\n        p = by_email[\\"old.ops@acme.example\\"]\\n        ids = [g.ct_event(p[\\"email\\"], \\"engineering\\", at(1, 13, 0), \\"AttachRolePolicy\\", \\"iam\\", p[\\"office_ip\\"],\\n                          {\\"roleName\\": \\"ops-tools\\", \\"policyArn\\": \\"arn:aws:iam::aws:policy/AdministratorAccess\\"}),\\n               g.ct_event(p[\\"email\\"], \\"engineering\\", at(33, 13, 0), \\"PutBucketPolicy\\", \\"s3\\", p[\\"office_ip\\"],\\n                          {\\"bucketName\\": \\"acme-ops-shared\\"})]\\n        labels[\\"scenarios\\"].append({\\"name\\": \\"gap_32_days\\", \\"identity\\": p[\\"email\\"], \\"days\\": 33,\\n                                    \\"expected\\": \\"not_linked\\", \\"event_ids\\": ids})\\n\\n    g.ct.sort(key=lambda r: r[\\"eventTime\\"])\\n    g.okta.sort(key=lambda r: r[\\"published\\"])\\n    labels[\\"events\\"] = {\\"okta\\": len(g.okta), \\"cloudtrail\\": len(g.ct)}\\n    return g.okta, g.ct, labels\\n\\n\\ndef write(out_dir: Path | str, days: int = 30, identities: int = 50, seed: int = 42,\\n          end: date | None = None) -> dict:\\n    out = Path(out_dir)\\n    (out / \\"okta\\").mkdir(parents=True, exist_ok=True)\\n    (out / \\"cloudtrail\\").mkdir(parents=True, exist_ok=True)\\n    okta, ct, labels = generate(days, identities, seed, end)\\n    (out / \\"okta\\" / \\"okta_synth.json\\").write_text(json.dumps(okta), encoding=\\"utf-8\\")\\n    (out / \\"cloudtrail\\" / \\"cloudtrail_synth.json\\").write_text(json.dumps({\\"Records\\": ct}), encoding=\\"utf-8\\")\\n    (out / \\"labels.json\\").write_text(json.dumps(labels, indent=1), encoding=\\"utf-8\\")\\n    return {\\"out\\": str(out), \\"okta_events\\": len(okta), \\"cloudtrail_events\\": len(ct),\\n            \\"scenarios\\": [s[\\"name\\"] for s in labels[\\"scenarios\\"]], \\"start\\": labels[\\"start\\"], \\"end\\": labels[\\"end\\"]}\\n\\n\\ndef report(engine, labels: dict) -> dict:\\n    \\"\\"\\"Compare findings with the synthetic ground truth.\\"\\"\\"\\n    findings = engine.findings(limit=1000)\\n    by_identity: dict[str, list[dict]] = {}\\n    for f in findings:\\n        by_identity.setdefault(f[\\"identity\\"], []).append(f)\\n    attack_ids = {s[\\"identity\\"] for s in labels.get(\\"scenarios\\", [])}\\n    rows = []\\n    for s in labels.get(\\"scenarios\\", []):\\n        fs = by_identity.get(s[\\"identity\\"], [])\\n        best = max(fs, key=lambda f: f[\\"risk\\"], default=None)\\n        if s[\\"expected\\"] == \\"linked\\":\\n            ok = best is not None and len(best[\\"stages\\"]) >= s.get(\\"min_stages\\", 2)\\n        else:\\n            ok = not any(set(s[\\"event_ids\\"]) <= set(f[\\"evidence\\"]) for f in fs)\\n        rows.append({\\"scenario\\": s[\\"name\\"], \\"identity\\": s[\\"identity\\"], \\"expected\\": s[\\"expected\\"], \\"passed\\": ok,\\n                     \\"risk\\": best[\\"risk\\"] if best else 0, \\"stages\\": best[\\"stages\\"] if best else [],\\n                     \\"days_spanned\\": best[\\"days_spanned\\"] if best else 0})\\n    false_pos = sorted(i for i in by_identity if i not in attack_ids)\\n    normal_total = labels.get(\\"identities\\", 0) - len(attack_ids)\\n    return {\\"scenarios\\": rows, \\"passed\\": sum(r[\\"passed\\"] for r in rows), \\"total\\": len(rows),\\n            \\"false_positive_identities\\": false_pos, \\"false_positive_count\\": len(false_pos),\\n            \\"normal_identities\\": normal_total, \\"synthetic\\": True}\\n", "static/js/memory30.js": "// IdentityShield 30-day memory page. All dynamic text is escaped (log data is untrusted).\\nconst API = \\"/api/memory\\";\\nconst $ = (id) => document.getElementById(id);\\n\\nconst esc = (v) => String(v ?? \\"\\").replace(/[&<>\\"\'`]/g, (c) => ({\\n  \\"&\\": \\"&amp;\\", \\"<\\": \\"&lt;\\", \\">\\": \\"&gt;\\", \'\\"\': \\"&quot;\\", \\"\'\\": \\"&#39;\\", \\"`\\": \\"&#96;\\" }[c]));\\nconst band = (r) => (r >= 90 ? \\"revoke\\" : r >= 70 ? \\"restrict\\" : r >= 40 ? \\"step_up\\" : \\"monitor\\");\\nconst BAND_COLOR = { monitor: \\"#94A3B8\\", step_up: \\"#E0A800\\", restrict: \\"#F08A4B\\", revoke: \\"#E5484D\\" };\\nconst STAGE_LABEL = {\\n  initial_access: \\"Initial access\\", persistence: \\"Persistence\\", discovery: \\"Discovery\\",\\n  privilege_escalation: \\"Privilege escalation\\", collection: \\"Collection\\", impact: \\"Impact\\",\\n  exfiltration: \\"Exfiltration\\", defense_evasion: \\"Defense evasion\\",\\n};\\nlet selected = null;\\n\\nfunction token() {\\n  try { return localStorage.getItem(\\"is_analyst_token\\") || \\"\\"; } catch { return \\"\\"; }\\n}\\nfunction saveToken(v) {\\n  try { localStorage.setItem(\\"is_analyst_token\\", v); } catch { /* storage unavailable */ }\\n}\\n\\nfunction toast(msg, isErr = false) {\\n  const t = $(\\"toast\\");\\n  t.textContent = msg;\\n  t.className = \\"toast\\" + (isErr ? \\" err\\" : \\"\\");\\n  t.style.display = \\"block\\";\\n  clearTimeout(toast._h);\\n  toast._h = setTimeout(() => { t.style.display = \\"none\\"; }, 4500);\\n}\\n\\nasync function api(path, opts = {}) {\\n  const ctrl = new AbortController();\\n  const timer = setTimeout(() => ctrl.abort(), opts.timeout || 60000);\\n  const headers = { \\"Content-Type\\": \\"application/json\\" };\\n  if (opts.method === \\"POST\\" && token()) headers[\\"X-Analyst-Token\\"] = token();\\n  try {\\n    const res = await fetch(API + path, { method: opts.method || \\"GET\\", headers,\\n      body: opts.body ? JSON.stringify(opts.body) : undefined, signal: ctrl.signal });\\n    const data = await res.json().catch(() => ({}));\\n    if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);\\n    return data;\\n  } finally {\\n    clearTimeout(timer);\\n  }\\n}\\n\\nfunction fmtBytes(n) {\\n  if (!n) return \\"0 KB\\";\\n  return n > 1048576 ? (n / 1048576).toFixed(1) + \\" MB\\" : Math.max(1, Math.round(n / 1024)) + \\" KB\\";\\n}\\nconst num = (n) => Number(n || 0).toLocaleString();\\n\\nfunction renderTiles(s) {\\n  const rows = s.rows || {};\\n  const tiles = [\\n    [\\"Database size\\", fmtBytes(s.db_size_bytes), \\"one SQLite file on this laptop\\"],\\n    [\\"Raw events kept\\", num(rows.events), s.last_prune\\n      ? `last ${s.retention?.raw_event_days ?? 7} days + evidence`\\n      : \\"retention not applied yet\\"],\\n    [\\"Evidence events\\", num(s.evidence_events), \\"kept as long as their case\\"],\\n    [\\"Identities\\", num(rows.identity_meta), `${num(rows.identity_daily)} daily summaries`],\\n    [\\"Linked findings\\", num(rows.findings), `${num(rows.chain_hits)} stage hits`],\\n    [\\"Memory window\\", s.memory_days?.first ? `${s.memory_days.first.slice(5)} \\u2192 ${s.memory_days.last.slice(5)}` : \\"empty\\",\\n      `${s.retention?.memory_days ?? 30}-day rolling memory`],\\n  ];\\n  $(\\"tiles\\").innerHTML = tiles.map(([k, v, sub]) =>\\n    `<div class=\\"card tile\\"><div class=\\"k\\">${esc(k)}</div><div class=\\"v\\">${esc(v)}</div><div class=\\"s\\">${esc(sub)}</div></div>`\\n  ).join(\\"\\");\\n}\\n\\nfunction renderBanner(rep) {\\n  if (!rep || rep.status === \\"no_synthetic_labels\\" || !rep.total) { $(\\"banner\\").innerHTML = \\"\\"; return; }\\n  const ok = rep.passed === rep.total && rep.false_positive_count === 0;\\n  $(\\"banner\\").innerHTML = `<div class=\\"banner ${ok ? \\"\\" : \\"warn\\"}\\"><span class=\\"tag\\">SYNTHETIC TEST DATA</span>\\n    <span>${esc(rep.passed)}/${esc(rep.total)} hidden multi-day attacks detected \\u00b7 ${esc(rep.false_positive_count)}\\n    false positives among ${esc(rep.normal_identities)} normal identities. Official KPIs use the official dataset only.</span></div>`;\\n}\\n\\nfunction renderFindings(list) {\\n  if (!list.length) {\\n    $(\\"findings\\").innerHTML = `<div class=\\"empty\\">No multi-day attack chains yet. Ingest data or generate the 30-day test set.</div>`;\\n    return;\\n  }\\n  $(\\"findings\\").innerHTML = list.map((f) => {\\n    const b = band(f.risk);\\n    return `<div class=\\"finding ${f.identity === selected ? \\"active\\" : \\"\\"}\\" data-id=\\"${esc(f.identity)}\\" tabindex=\\"0\\" role=\\"button\\">\\n      <div class=\\"frow\\"><span class=\\"who\\">${esc(f.identity)}</span>\\n        <span class=\\"badge b-${b}\\">risk ${esc(Math.round(f.risk))}</span></div>\\n      <div class=\\"chips\\">${f.stages.map((s) => `<span class=\\"stage st-${esc(s)}\\">${esc(STAGE_LABEL[s] || s)}</span>`).join(\\"\\")}</div>\\n      <div class=\\"meta\\">${esc(f.days_spanned)} day(s) of evidence \\u00b7 ${esc(f.first_time.slice(0, 10))} \\u2192 ${esc(f.last_time.slice(0, 10))}</div>\\n      <div class=\\"narr\\">${esc(f.narrative)}</div></div>`;\\n  }).join(\\"\\");\\n  document.querySelectorAll(\\".finding\\").forEach((el) => {\\n    const open = () => loadIdentity(el.dataset.id);\\n    el.addEventListener(\\"click\\", open);\\n    el.addEventListener(\\"keydown\\", (e) => { if (e.key === \\"Enter\\" || e.key === \\" \\") { e.preventDefault(); open(); } });\\n  });\\n}\\n\\nfunction stripSvg(days) {\\n  const W = 30 * 22 + 40, H = 170, base = 130, x0 = 30;\\n  const n = days.length, bw = Math.max(6, Math.floor((W - x0 - 10) / n) - 4);\\n  let s = `<svg viewBox=\\"0 0 ${W} ${H}\\" width=\\"100%\\" role=\\"img\\" aria-label=\\"Risk per day over the last ${n} days\\">`;\\n  [0, 40, 70, 90].forEach((v) => {\\n    const y = base - (v / 100) * 110;\\n    s += `<line x1=\\"${x0}\\" x2=\\"${W - 6}\\" y1=\\"${y}\\" y2=\\"${y}\\" stroke=\\"#EFE8DC\\"/>`;\\n    s += `<text x=\\"${x0 - 6}\\" y=\\"${y + 4}\\" font-size=\\"10\\" text-anchor=\\"end\\" fill=\\"#6B7280\\">${v}</text>`;\\n  });\\n  days.forEach((d, i) => {\\n    const x = x0 + 6 + i * (bw + 4);\\n    const r = d.max_risk || 0;\\n    const h = Math.max(r > 0 ? 3 : 0, (r / 100) * 110);\\n    const activity = Math.min(1, (d.events || 0) / 40);\\n    s += `<rect x=\\"${x}\\" y=\\"${base - 6 * activity}\\" width=\\"${bw}\\" height=\\"${6 * activity}\\" fill=\\"#E8E1D6\\" rx=\\"2\\"/>`;\\n    if (h) s += `<rect x=\\"${x}\\" y=\\"${base - h}\\" width=\\"${bw}\\" height=\\"${h}\\" rx=\\"3\\" fill=\\"${BAND_COLOR[band(r)]}\\">\\n      <title>${esc(d.day)}: risk ${Math.round(r)} \\u00b7 ${esc(d.events)} events${d.hits.length ? \\" \\u00b7 \\" + esc(d.hits.join(\\", \\")) : \\"\\"}</title></rect>`;\\n    if (d.hits.length) s += `<circle cx=\\"${x + bw / 2}\\" cy=\\"${base + 12}\\" r=\\"4\\" fill=\\"#6D4FD8\\"><title>${esc(d.hits.join(\\", \\"))}</title></circle>`;\\n    if (i % 5 === 0 || i === n - 1) s += `<text x=\\"${x + bw / 2}\\" y=\\"${H - 8}\\" font-size=\\"10\\" text-anchor=\\"middle\\" fill=\\"#4B5263\\">${esc(d.day.slice(5))}</text>`;\\n  });\\n  return s + \\"</svg>\\";\\n}\\n\\nasync function loadIdentity(identity) {\\n  selected = identity;\\n  document.querySelectorAll(\\".finding\\").forEach((el) => el.classList.toggle(\\"active\\", el.dataset.id === identity));\\n  $(\\"idTitle\\").textContent = \\"Identity memory: \\" + identity;\\n  $(\\"identity\\").innerHTML = `<div class=\\"skel\\"></div>`;\\n  try {\\n    const v = await api(`/identity/${encodeURIComponent(identity)}?days=30`);\\n    const hits = v.hits.map((h) => `<tr><td class=\\"mono\\">${esc(h.day)}</td>\\n        <td><span class=\\"stage st-${esc(h.stage)}\\">${esc(STAGE_LABEL[h.stage] || h.stage)}</span></td>\\n        <td>${esc(h.label)}${h.detail && (h.detail.action || h.detail.resource) ? `<div class=\\"meta\\">${esc([h.detail.action, h.detail.resource].filter(Boolean).join(\\" \\u00b7 \\"))}</div>` : \\"\\"}</td>\\n        <td><button class=\\"linkbtn\\" data-ids=\\"${esc(h.event_ids.join(\\",\\"))}\\" type=\\"button\\">${esc(h.event_ids.length)} event(s)</button></td></tr>`).join(\\"\\");\\n    $(\\"identity\\").innerHTML = `\\n      <div class=\\"frow\\"><span class=\\"meta\\">Window ${esc(v.window.start)} \\u2192 ${esc(v.window.end)} \\u00b7 first seen ${esc(v.first_seen.slice(0, 10))}</span>\\n        <span class=\\"badge b-${band(v.risk_now)}\\">identity risk now ${esc(Math.round(v.risk_now))} (peak ${esc(Math.round(v.risk_peak))})</span></div>\\n      <div class=\\"legend\\"><span><i style=\\"background:#E5484D\\"></i>risk \\u2265 90</span><span><i style=\\"background:#F08A4B\\"></i>70\\u201389</span>\\n        <span><i style=\\"background:#E0A800\\"></i>40\\u201369</span><span><i style=\\"background:#E8E1D6\\"></i>daily activity</span>\\n        <span><i style=\\"background:#6D4FD8;border-radius:50%\\"></i>attack-stage hit</span></div>\\n      <div class=\\"strip-wrap\\">${stripSvg(v.days)}</div>\\n      <h2 style=\\"margin-top:16px\\">Stage hits remembered</h2>\\n      ${v.hits.length ? `<div style=\\"max-height:320px;overflow:auto\\"><table><thead><tr><th>Day</th><th>Stage</th><th>What</th><th>Evidence</th></tr></thead><tbody>${hits}</tbody></table></div>`\\n        : `<div class=\\"empty\\">No attack-stage hits for this identity in the window.</div>`}\\n      <div id=\\"evidence\\"></div>`;\\n    document.querySelectorAll(\\"#identity .linkbtn\\").forEach((b) => b.addEventListener(\\"click\\", () => showEvidence(b.dataset.ids)));\\n  } catch (e) {\\n    $(\\"identity\\").innerHTML = `<div class=\\"empty\\">Could not load: ${esc(e.message)}</div>`;\\n  }\\n}\\n\\nasync function showEvidence(ids) {\\n  const box = $(\\"evidence\\");\\n  box.innerHTML = `<div class=\\"skel\\" style=\\"margin-top:12px\\"></div>`;\\n  try {\\n    const d = await api(`/evidence?ids=${encodeURIComponent(ids)}`);\\n    if (!d.events.length) { box.innerHTML = `<div class=\\"empty\\" style=\\"margin-top:12px\\">Evidence pruned or not found.</div>`; return; }\\n    const lines = d.events.map((e) => {\\n      let raw = e.raw;\\n      try { raw = JSON.stringify(JSON.parse(e.raw), null, 2); } catch { /* keep text */ }\\n      return `${e.time}  ${e.source}  ${e.action}  ${e.resource || \\"\\"}\\\\n${raw}`;\\n    }).join(\\"\\\\n\\\\n\\");\\n    box.innerHTML = `<pre>${esc(lines)}</pre>`;\\n  } catch (e) {\\n    box.innerHTML = `<div class=\\"empty\\">Could not load evidence: ${esc(e.message)}</div>`;\\n  }\\n}\\n\\nasync function refresh() {\\n  try {\\n    const [s, f, rep] = await Promise.all([api(\\"/stats\\"), api(\\"/findings?limit=50\\"), api(\\"/report\\").catch(() => null)]);\\n    renderTiles(s);\\n    renderFindings(f.findings);\\n    renderBanner(rep);\\n    const wanted = new URLSearchParams(location.search).get(\\"identity\\");\\n    if (!selected && wanted) loadIdentity(wanted);\\n    else if (!selected && f.findings.length) loadIdentity(f.findings[0].identity);\\n  } catch (e) {\\n    toast(\\"Memory API not reachable: \\" + e.message, true);\\n    $(\\"findings\\").innerHTML = `<div class=\\"empty\\">Memory API not reachable. Is the server running?</div>`;\\n  }\\n}\\n\\nasync function run(btn, fn, okMsg) {\\n  if (btn.disabled) return;\\n  btn.disabled = true;\\n  btn.classList.add(\\"is-loading\\");\\n  try {\\n    const out = await fn();\\n    toast(okMsg(out));\\n    selected = null;\\n    await refresh();\\n  } catch (e) {\\n    toast(e.message, true);\\n  } finally {\\n    btn.disabled = false;\\n    btn.classList.remove(\\"is-loading\\");\\n  }\\n}\\n\\nfunction init() {\\n  $(\\"token\\").value = token();\\n  $(\\"token\\").addEventListener(\\"change\\", (e) => saveToken(e.target.value.trim()));\\n  $(\\"btnSynth\\").addEventListener(\\"click\\", (e) => run(e.currentTarget,\\n    () => api(\\"/synth\\", { method: \\"POST\\", body: { days: 30, identities: 200, seed: 42, ingest: true, reset_first: true }, timeout: 180000 }),\\n    (o) => `Generated ${num(o.ingest?.inserted)} events over 30 days \\u00b7 ${o.report?.passed}/${o.report?.total} attacks detected`));\\n  $(\\"btnIngest\\").addEventListener(\\"click\\", (e) => run(e.currentTarget,\\n    () => api(\\"/ingest\\", { method: \\"POST\\", body: {}, timeout: 180000 }),\\n    (o) => `Ingested ${num(o.inserted)} new events from ${num(o.files)} file(s)`));\\n  $(\\"btnPrune\\").addEventListener(\\"click\\", (e) => run(e.currentTarget,\\n    () => api(\\"/prune\\", { method: \\"POST\\", body: { vacuum: true } }),\\n    (o) => `Retention applied: ${num(o.events_deleted)} raw events removed, ${num(o.evidence_kept)} evidence events kept`));\\n  refresh();\\n}\\n\\ninit();\\n", "static/memory.html": "<!doctype html>\\n<html lang=\\"en\\">\\n<head>\\n<meta charset=\\"utf-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">\\n<title>IdentityShield \\u00b7 30-Day Memory</title>\\n<link rel=\\"preconnect\\" href=\\"https://fonts.googleapis.com\\">\\n<link href=\\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap\\" rel=\\"stylesheet\\">\\n<style>\\n:root{\\n  --bg:#FBF8F3; --surface:#FFFFFF; --surface-2:#F6F1E9; --surface-3:#EFE8DC; --border:#E8E1D6;\\n  --ink:#1F2430; --ink-2:#4B5263; --muted:#6B7280; --focus:#3D6FE0;\\n  --sky:#DCE8FF; --sky-s:#3D6FE0; --mint:#D9F2EA; --mint-s:#0F8A6A; --peach:#FFE4D3; --peach-s:#C2410C;\\n  --butter:#FFF3C4; --butter-s:#A16207; --rose:#FFE0E0; --rose-s:#C81E1E; --lav:#ECE6FF; --lav-s:#6D4FD8;\\n  --stone:#EEF0F3; --stone-s:#475569;\\n  --shadow:0 1px 2px rgba(31,36,48,.04),0 8px 24px rgba(31,36,48,.06);\\n  --shadow-up:0 2px 4px rgba(31,36,48,.05),0 16px 40px rgba(31,36,48,.09);\\n}\\n*{box-sizing:border-box}\\nbody{margin:0;font-family:Inter,system-ui,-apple-system,\\"Segoe UI\\",sans-serif;color:var(--ink);\\n  background:linear-gradient(180deg,#FFFDF9 0%,#FBF8F3 55%,#F7F2EA 100%) fixed;font-size:14px;line-height:1.45}\\na{color:var(--sky-s)}\\n.wrap{max-width:1240px;margin:0 auto;padding:24px 24px 64px}\\n.top{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:20px}\\n.top h1{font-size:28px;font-weight:600;margin:0 0 4px}\\n.top p{margin:0;color:var(--ink-2)}\\n.back{font-size:13px;text-decoration:none;color:var(--ink-2)}\\n.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\\n.card{background:var(--surface);border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow);padding:20px}\\n.grid{display:grid;gap:20px}\\n.tiles{grid-template-columns:repeat(6,minmax(0,1fr))}\\n@media (max-width:1100px){.tiles{grid-template-columns:repeat(3,minmax(0,1fr))}}\\n@media (max-width:640px){.tiles{grid-template-columns:repeat(2,minmax(0,1fr))}}\\n.tile .k{font-size:12px;font-weight:500;color:var(--ink-2)}\\n.tile .v{font-size:22px;font-weight:600;margin-top:4px;font-family:\\"JetBrains Mono\\",monospace}\\n.tile .s{font-size:12px;color:var(--muted);margin-top:2px}\\n.main{grid-template-columns:minmax(0,5fr) minmax(0,7fr);margin-top:20px}\\n@media (max-width:1000px){.main{grid-template-columns:1fr}}\\nh2{font-size:18px;font-weight:600;margin:0 0 12px}\\n.btn{position:relative;overflow:hidden;border:0;border-radius:12px;padding:10px 16px;font:600 14px Inter,sans-serif;\\n  cursor:pointer;transition:transform .12s cubic-bezier(.2,.8,.2,1),box-shadow .12s,background .12s;\\n  display:inline-flex;align-items:center;gap:8px}\\n.btn-primary{background:#3D6FE0;color:#fff;box-shadow:0 3px 0 #2A4FA8,0 6px 14px rgba(61,111,224,.18)}\\n.btn-primary:hover{background:#355FC4;transform:translateY(-1px)}\\n.btn-primary:active{transform:translateY(3px);box-shadow:0 0 0 #2A4FA8,0 2px 6px rgba(61,111,224,.18)}\\n.btn-secondary{background:#fff;color:var(--ink);border:1px solid var(--border);box-shadow:0 3px 0 #D8CFC2}\\n.btn-secondary:hover{transform:translateY(-1px)}\\n.btn-secondary:active{transform:translateY(3px);box-shadow:0 0 0 #D8CFC2}\\n.btn:focus-visible{outline:2px solid var(--focus);outline-offset:2px}\\n.btn[disabled]{opacity:.5;cursor:not-allowed;transform:none}\\n.btn.is-loading{color:transparent}\\n.btn.is-loading::after{content:\\"\\";position:absolute;inset:0;margin:auto;width:16px;height:16px;border-radius:50%;\\n  border:2px solid rgba(255,255,255,.9);border-right-color:transparent;animation:spin .7s linear infinite}\\n.btn-secondary.is-loading::after{border-color:var(--sky-s);border-right-color:transparent}\\n@keyframes spin{to{transform:rotate(360deg)}}\\n.token{border:1px solid var(--border);background:#fff;border-radius:10px;padding:9px 10px;font:13px Inter,sans-serif;\\n  width:150px;box-shadow:inset 0 1px 2px rgba(31,36,48,.06)}\\n.token:focus{outline:2px solid var(--focus);outline-offset:1px}\\n.banner{margin-top:20px;display:flex;gap:12px;align-items:center;background:var(--mint);color:var(--mint-s);\\n  border:1px solid #BFE6D8;border-radius:14px;padding:12px 16px;font-weight:500}\\n.banner.warn{background:var(--butter);color:var(--butter-s);border-color:#F2E2A0}\\n.tag{font-size:11px;font-weight:700;letter-spacing:.04em;border-radius:999px;padding:3px 8px;background:#fff;\\n  border:1px solid currentColor}\\n.finding{border:1px solid var(--border);border-radius:14px;padding:14px;margin-bottom:12px;cursor:pointer;\\n  transition:box-shadow .15s,transform .15s;background:#fff}\\n.finding:hover,.finding.active{box-shadow:var(--shadow-up);transform:translateY(-1px)}\\n.finding.active{border-color:#B9CCF7}\\n.frow{display:flex;justify-content:space-between;gap:8px;align-items:center}\\n.who{font-weight:600;font-family:\\"JetBrains Mono\\",monospace;font-size:13px;word-break:break-all}\\n.badge{border-radius:999px;padding:3px 10px;font-size:12px;font-weight:700;white-space:nowrap}\\n.b-monitor{background:var(--stone);color:var(--stone-s)}.b-step_up{background:var(--butter);color:var(--butter-s)}\\n.b-restrict{background:var(--peach);color:var(--peach-s)}.b-revoke{background:var(--rose);color:var(--rose-s)}\\n.chips{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 6px}\\n.chip{border-radius:999px;padding:2px 9px;font-size:12px;font-weight:600;background:var(--lav);color:var(--lav-s)}\\n.meta{font-size:12px;color:var(--ink-2)}\\n.narr{font-size:13px;color:var(--ink-2);margin-top:6px}\\n.empty{color:var(--ink-2);padding:24px;text-align:center;background:var(--surface-2);border-radius:14px}\\n.strip-wrap{overflow-x:auto}\\nsvg text{font-family:Inter,sans-serif}\\n.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:12px;color:var(--ink-2);margin:8px 0 4px}\\n.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:5px;vertical-align:-1px}\\ntable{width:100%;border-collapse:collapse;font-size:13px}\\nth{text-align:left;background:var(--surface-2);color:var(--ink-2);font-weight:600;padding:8px 10px;position:sticky;top:0}\\ntd{padding:8px 10px;border-top:1px solid var(--border);vertical-align:top}\\ntd.mono{font-family:\\"JetBrains Mono\\",monospace;font-size:12px}\\n.stage{border-radius:999px;padding:2px 8px;font-size:11px;font-weight:700;white-space:nowrap}\\n.st-initial_access{background:var(--sky);color:var(--sky-s)}.st-persistence{background:var(--butter);color:var(--butter-s)}\\n.st-discovery{background:var(--stone);color:var(--stone-s)}.st-privilege_escalation{background:var(--peach);color:var(--peach-s)}\\n.st-collection{background:var(--lav);color:var(--lav-s)}.st-impact{background:var(--rose);color:var(--rose-s)}\\n.st-exfiltration{background:var(--rose);color:var(--rose-s)}.st-defense_evasion{background:var(--rose);color:var(--rose-s)}\\n.linkbtn{background:none;border:0;color:var(--sky-s);font:600 12px Inter,sans-serif;cursor:pointer;padding:0}\\npre{background:#FFFDF9;border:1px solid var(--border);border-radius:12px;padding:12px;font:12px \\"JetBrains Mono\\",monospace;\\n  white-space:pre-wrap;word-break:break-word;max-height:320px;overflow:auto;margin:10px 0 0}\\n.toast{position:fixed;right:20px;bottom:20px;background:#fff;border:1px solid var(--border);box-shadow:var(--shadow-up);\\n  border-radius:12px;padding:12px 16px;max-width:420px;display:none}\\n.toast.err{border-color:#F5C2C2;color:var(--rose-s)}\\n.skel{height:14px;border-radius:7px;background:linear-gradient(90deg,#F6F1E9,#EFE8DC,#F6F1E9);background-size:200% 100%;\\n  animation:sh 1.2s infinite}\\n@keyframes sh{to{background-position:-200% 0}}\\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\\n</style>\\n</head>\\n<body>\\n<div class=\\"wrap\\">\\n  <div class=\\"top\\">\\n    <div>\\n      <a class=\\"back\\" href=\\"/\\">\\u2190 Back to dashboard</a>\\n      <h1>30-Day Identity Memory</h1>\\n      <p>Slow attacks spread over days or weeks, linked into one story per identity. Raw events kept 7 days, evidence kept with its case, a compact daily memory kept 30 days.</p>\\n    </div>\\n    <div class=\\"actions\\">\\n      <input id=\\"token\\" class=\\"token\\" type=\\"password\\" placeholder=\\"Analyst token\\" autocomplete=\\"off\\" aria-label=\\"Analyst token\\">\\n      <button id=\\"btnSynth\\" class=\\"btn btn-primary\\" type=\\"button\\">Generate 30-day test data</button>\\n      <button id=\\"btnIngest\\" class=\\"btn btn-secondary\\" type=\\"button\\">Ingest dataset</button>\\n      <button id=\\"btnPrune\\" class=\\"btn btn-secondary\\" type=\\"button\\">Apply retention</button>\\n    </div>\\n  </div>\\n\\n  <div id=\\"tiles\\" class=\\"grid tiles\\"></div>\\n  <div id=\\"banner\\"></div>\\n\\n  <div class=\\"grid main\\">\\n    <section class=\\"card\\">\\n      <h2>Linked multi-day findings</h2>\\n      <div id=\\"findings\\"><div class=\\"skel\\"></div></div>\\n    </section>\\n    <section class=\\"card\\">\\n      <h2 id=\\"idTitle\\">Identity memory</h2>\\n      <div id=\\"identity\\"><div class=\\"empty\\">Select a finding to see that identity\'s last 30 days.</div></div>\\n    </section>\\n  </div>\\n</div>\\n<div id=\\"toast\\" class=\\"toast\\" role=\\"status\\" aria-live=\\"polite\\"></div>\\n<script type=\\"module\\" src=\\"/js/memory30.js\\"></script>\\n</body>\\n</html>\\n", "tests/test_memory30.py": "\\"\\"\\"Tests for the 30-day identity memory (app/memory30). No network, no sleeping: time comes from event data.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport json\\nfrom collections import defaultdict\\nfrom datetime import date, datetime, timedelta, timezone\\n\\nimport pytest\\n\\nfrom app.memory30 import config, synth\\nfrom app.memory30.engine import MemoryEngine\\nfrom app.memory30.normalize import cloudtrail_identity, network_of, normalize, parse_json_text\\n\\nEND = date(2026, 10, 31)\\n\\n\\ndef _ct(eid, when, name, ip=\\"198.51.100.9\\", email=\\"dev@acme.example\\", params=None, source=\\"iam\\", error=None):\\n    rec = {\\"eventID\\": eid, \\"eventTime\\": when.strftime(\\"%Y-%m-%dT%H:%M:%SZ\\"), \\"eventName\\": name,\\n           \\"eventSource\\": f\\"{source}.amazonaws.com\\", \\"sourceIPAddress\\": ip,\\n           \\"userIdentity\\": {\\"type\\": \\"AssumedRole\\", \\"arn\\": f\\"arn:aws:sts::1:assumed-role/eng-role/{email}\\"},\\n           \\"requestParameters\\": params or {}}\\n    if error:\\n        rec[\\"errorCode\\"] = error\\n    return rec\\n\\n\\ndef _okta(eid, when, email=\\"dev@acme.example\\", ip=\\"198.51.100.9\\", asn=64500, proxy=False):\\n    return {\\"uuid\\": eid, \\"published\\": when.strftime(\\"%Y-%m-%dT%H:%M:%S.000Z\\"), \\"eventType\\": \\"user.session.start\\",\\n            \\"actor\\": {\\"alternateId\\": email}, \\"client\\": {\\"ipAddress\\": ip},\\n            \\"securityContext\\": {\\"asNumber\\": asn, \\"isProxy\\": proxy}, \\"outcome\\": {\\"result\\": \\"SUCCESS\\"}}\\n\\n\\ndef _t(day: int, hour: int = 10) -> datetime:\\n    d = END - timedelta(days=40) + timedelta(days=day)\\n    return datetime(d.year, d.month, d.day, hour, tzinfo=timezone.utc)\\n\\n\\ndef _normal_history(days=range(0, 5), email=\\"dev@acme.example\\"):\\n    out = []\\n    for d in days:\\n        out.append(_okta(f\\"n-okta-{email}-{d}\\", _t(d, 9), email=email))\\n        out.append(_ct(f\\"n-ct-{email}-{d}\\", _t(d, 10), \\"GetObject\\", email=email, source=\\"s3\\",\\n                       params={\\"bucketName\\": \\"acme-eng-shared\\", \\"key\\": \\"a.txt\\"}))\\n    return out\\n\\n\\n@pytest.fixture()\\ndef eng(tmp_path):\\n    e = MemoryEngine(tmp_path / \\"mem.sqlite\\")\\n    yield e\\n    e.close()\\n\\n\\n# ---------------------------------------------------------------- normalization\\ndef test_normalize_okta_and_cloudtrail_identity_resolution():\\n    o = normalize(_okta(\\"u1\\", _t(1), email=\\"Alice@Acme.example\\", proxy=True))\\n    assert o[\\"identity\\"] == \\"alice@acme.example\\" and o[\\"source\\"] == \\"okta\\"\\n    assert o[\\"net\\"] == \\"asn:64500\\" and o[\\"is_proxy\\"] is True and o[\\"category\\"] == \\"login\\"\\n    c = normalize(_ct(\\"e1\\", _t(1), \\"AttachUserPolicy\\", email=\\"alice@acme.example\\",\\n                      params={\\"policyArn\\": \\"arn:aws:iam::aws:policy/AdministratorAccess\\"}))\\n    assert c[\\"identity\\"] == \\"alice@acme.example\\" and c[\\"category\\"] == \\"privesc\\"\\n    assert cloudtrail_identity({\\"type\\": \\"SAMLUser\\", \\"userName\\": \\"Bob@acme.example\\"})[0] == \\"bob@acme.example\\"\\n    assert cloudtrail_identity({\\"type\\": \\"IAMUser\\", \\"userName\\": \\"svc-report\\"})[0] == \\"svc-report\\"\\n    assert network_of(\\"198.51.100.7\\") == \\"v4:198.51.0.0\\" and network_of(\\"s3.amazonaws.com\\") is None\\n    assert normalize({\\"foo\\": 1}) is None\\n\\n\\ndef test_parse_json_formats():\\n    assert len(parse_json_text(json.dumps({\\"Records\\": [{\\"a\\": 1}, {\\"b\\": 2}]}))) == 2\\n    assert len(parse_json_text(json.dumps([{\\"a\\": 1}]))) == 1\\n    assert len(parse_json_text(\'{\\"a\\": 1}\\\\n{\\"b\\": 2}\\\\n\')) == 2\\n    assert parse_json_text(\\"\\") == []\\n\\n\\n# ---------------------------------------------------------------- ingest\\ndef test_ingest_is_idempotent(eng):\\n    recs = _normal_history()\\n    first = eng.ingest_records(recs)\\n    second = eng.ingest_records(recs)\\n    assert first[\\"inserted\\"] == len(recs) and second[\\"inserted\\"] == 0 and second[\\"duplicates\\"] == len(recs)\\n    assert eng.stats()[\\"rows\\"][\\"events\\"] == len(recs)\\n\\n\\ndef test_slow_chain_over_14_days_is_linked(eng):\\n    recs = _normal_history(range(0, 6))\\n    recs += [_okta(\\"a1\\", _t(6, 21), ip=\\"185.220.101.23\\", asn=64510, proxy=True),\\n             _ct(\\"a2\\", _t(11, 22), \\"CreateAccessKey\\", ip=\\"185.220.101.23\\", params={\\"userName\\": \\"dev\\"})]\\n    recs += [_ct(f\\"a3-{i}\\", _t(15, 22) + timedelta(minutes=i), n, ip=\\"185.220.101.23\\", source=s)\\n             for i, (n, s) in enumerate([(\\"ListUsers\\", \\"iam\\"), (\\"ListRoles\\", \\"iam\\"), (\\"ListBuckets\\", \\"s3\\"),\\n                                         (\\"DescribeInstances\\", \\"ec2\\"), (\\"ListSecrets\\", \\"secretsmanager\\")])]\\n    recs += [_ct(\\"a4\\", _t(20, 22), \\"AttachUserPolicy\\", ip=\\"185.220.101.23\\",\\n                 params={\\"userName\\": \\"dev\\", \\"policyArn\\": \\"arn:aws:iam::aws:policy/AdministratorAccess\\"})]\\n    eng.ingest_records(recs)\\n    fs = eng.findings(identity=\\"dev@acme.example\\")\\n    assert len(fs) == 1\\n    f = fs[0]\\n    assert {\\"initial_access\\", \\"persistence\\", \\"discovery\\", \\"privilege_escalation\\"} <= set(f[\\"stages\\"])\\n    assert f[\\"risk\\"] >= 90 and f[\\"days_spanned\\"] >= 4\\n    assert \\"okta:a1\\" in f[\\"evidence\\"] and \\"cloudtrail:a4\\" in f[\\"evidence\\"]\\n\\n\\ndef test_steps_32_days_apart_are_not_linked(eng):\\n    recs = _normal_history(range(0, 4))\\n    recs += [_ct(\\"g1\\", _t(4), \\"AttachRolePolicy\\", params={\\"roleName\\": \\"x\\"}),\\n             _ct(\\"g2\\", _t(36), \\"CreateAccessKey\\", params={\\"userName\\": \\"dev\\"})]\\n    eng.ingest_records(recs)\\n    for f in eng.findings(identity=\\"dev@acme.example\\"):\\n        assert not {\\"cloudtrail:g1\\", \\"cloudtrail:g2\\"} <= set(f[\\"evidence\\"])\\n\\n\\ndef test_routine_team_writes_are_not_suspicious(eng):\\n    recs = []\\n    for who in (\\"f1\\", \\"f2\\", \\"f3\\", \\"f4\\"):\\n        email = f\\"{who}@acme.example\\"\\n        recs += _normal_history(range(0, 6), email=email)\\n        day = 1 if who != \\"f4\\" else 5          # f4 writes for the first time after the baseline period\\n        recs.append(_ct(f\\"w-{who}\\", _t(day, 11), \\"PutObject\\", email=email, source=\\"s3\\",\\n                        params={\\"bucketName\\": \\"acme-finance-shared\\", \\"key\\": \\"r.pdf\\"}))\\n    eng.ingest_records(recs)\\n    assert eng.findings() == []\\n    hits = eng.store.query(\\"SELECT * FROM chain_hits WHERE kind=\'modify_sensitive\'\\")\\n    assert hits == []   # shared team resource: >= 3 other writers\\n\\n\\ndef test_prune_keeps_evidence_and_findings(eng):\\n    test_slow_chain_over_14_days_is_linked(eng)\\n    before = eng.stats()[\\"rows\\"][\\"events\\"]\\n    out = eng.prune(now=_t(30))\\n    assert out[\\"events_deleted\\"] > 0\\n    left = eng.store.query(\\"SELECT event_id, evidence FROM events\\")\\n    assert all(r[\\"evidence\\"] == 1 for r in left if r[\\"event_id\\"] < \\"zzz\\" and r[\\"event_id\\"].startswith(\\n        (\\"cloudtrail:a\\", \\"okta:a\\")))\\n    assert len(eng.findings()) == 1 and eng.stats()[\\"rows\\"][\\"events\\"] < before\\n    assert out[\\"evidence_kept\\"] >= 4\\n\\n\\ndef test_memory_survives_restart(tmp_path):\\n    db = tmp_path / \\"restart.sqlite\\"\\n    e1 = MemoryEngine(db)\\n    e1.ingest_records(_normal_history(range(0, 6)) + [\\n        _okta(\\"r1\\", _t(6, 21), ip=\\"185.220.101.23\\", asn=64510, proxy=True),\\n        _ct(\\"r2\\", _t(9, 22), \\"CreateAccessKey\\", ip=\\"185.220.101.23\\", params={\\"userName\\": \\"dev\\"})])\\n    before = e1.findings(identity=\\"dev@acme.example\\")\\n    assert len(before) == 1 and \\"privilege_escalation\\" not in before[0][\\"stages\\"]\\n    e1.close()\\n    e2 = MemoryEngine(db)                       # \\"app restarted\\"\\n    e2.ingest_records([_ct(\\"r3\\", _t(18, 22), \\"AttachUserPolicy\\", ip=\\"185.220.101.23\\",\\n                           params={\\"userName\\": \\"dev\\", \\"policyArn\\": \\"arn:aws:iam::aws:policy/AdministratorAccess\\"})])\\n    fs = e2.findings(identity=\\"dev@acme.example\\")\\n    assert len(fs) == 1 and fs[0][\\"finding_id\\"] == before[0][\\"finding_id\\"]      # same case, extended\\n    assert \\"okta:r1\\" in fs[0][\\"evidence\\"] and \\"cloudtrail:r3\\" in fs[0][\\"evidence\\"]\\n    assert \\"privilege_escalation\\" in fs[0][\\"stages\\"] and fs[0][\\"risk\\"] >= before[0][\\"risk\\"]\\n    e2.close()\\n\\n\\ndef test_identity_view_has_30_days(eng):\\n    test_slow_chain_over_14_days_is_linked(eng)\\n    v = eng.identity_view(\\"dev@acme.example\\", days=30)\\n    assert len(v[\\"days\\"]) == 30 and v[\\"risk_peak\\"] >= 90\\n    assert any(d[\\"max_risk\\"] > 0 for d in v[\\"days\\"]) and v[\\"findings\\"]\\n    assert eng.identity_view(\\"nobody@x\\", 30) is None\\n\\n\\n# ---------------------------------------------------------------- full synthetic 30 days\\n@pytest.fixture(scope=\\"module\\")\\ndef synth_run(tmp_path_factory):\\n    tmp = tmp_path_factory.mktemp(\\"synth\\")\\n    okta, ct, labels = synth.generate(days=30, identities=60, seed=42, end=END)\\n    e = MemoryEngine(tmp / \\"s.sqlite\\")\\n    e.ingest_records(okta + ct)\\n    yield e, labels, okta, ct\\n    e.close()\\n\\n\\ndef test_synthetic_30_days_detects_all_scenarios_without_false_positives(synth_run):\\n    e, labels, _, _ = synth_run\\n    rep = synth.report(e, labels)\\n    assert rep[\\"total\\"] == 3 and rep[\\"passed\\"] == 3, rep\\n    assert rep[\\"false_positive_count\\"] == 0, rep[\\"false_positive_identities\\"]\\n    heist = next(f for f in e.findings() if f[\\"identity\\"] == \\"safe.dev@acme.example\\")\\n    assert heist[\\"days_spanned\\"] >= 10      # slow heist evidence spans many days\\n    insider = next(f for f in e.findings() if f[\\"identity\\"] == \\"meera.ops@acme.example\\")\\n    assert insider[\\"days_spanned\\"] >= 3\\n\\n\\ndef test_day_by_day_live_ingest_matches_batch(synth_run, tmp_path):\\n    e_batch, labels, okta, ct = synth_run\\n    by_day = defaultdict(list)\\n    for r in okta:\\n        by_day[r[\\"published\\"][:10]].append(r)\\n    for r in ct:\\n        by_day[r[\\"eventTime\\"][:10]].append(r)\\n    live = MemoryEngine(tmp_path / \\"live.sqlite\\")\\n    for d in sorted(by_day):\\n        live.ingest_records(by_day[d])\\n    batch_ids = {f[\\"identity\\"] for f in e_batch.findings()}\\n    live_ids = {f[\\"identity\\"] for f in live.findings()}\\n    assert live_ids == batch_ids\\n    assert synth.report(live, labels)[\\"passed\\"] == 3\\n    live.close()\\n\\n\\ndef test_storage_stays_small(synth_run):\\n    e, _, _, _ = synth_run\\n    st = e.stats()\\n    assert st[\\"db_size_mb\\"] < 200 and st[\\"rows\\"][\\"identity_daily\\"] > 0\\n    assert st[\\"retention\\"][\\"memory_days\\"] == config.MEMORY_RETENTION_DAYS\\n\\n\\ndef test_gap_scenario_in_40_day_synthetic(tmp_path):\\n    okta, ct, labels = synth.generate(days=40, identities=30, seed=7, end=END)\\n    e = MemoryEngine(tmp_path / \\"g.sqlite\\")\\n    e.ingest_records(okta + ct)\\n    rep = synth.report(e, labels)\\n    gap = next(r for r in rep[\\"scenarios\\"] if r[\\"scenario\\"] == \\"gap_32_days\\")\\n    assert gap[\\"passed\\"] and rep[\\"passed\\"] == rep[\\"total\\"]\\n    e.close()\\n\\n\\n# ---------------------------------------------------------------- API (runs where FastAPI is installed)\\ndef test_api_routes(tmp_path, monkeypatch):\\n    fastapi = pytest.importorskip(\\"fastapi\\")\\n    from fastapi.testclient import TestClient\\n\\n    monkeypatch.setattr(config, \\"DB_PATH\\", tmp_path / \\"api.sqlite\\")\\n    monkeypatch.setattr(config, \\"SYNTH_DIR\\", tmp_path / \\"synth\\")\\n    monkeypatch.setattr(config, \\"DATA_DIR\\", tmp_path)\\n    monkeypatch.setenv(\\"ANALYST_TOKEN\\", \\"t0k3n\\")\\n    from app.memory30 import api\\n    monkeypatch.setattr(api, \\"_engine\\", None)\\n    app = fastapi.FastAPI()\\n    app.include_router(api.router, prefix=\\"/api/memory\\")\\n    client = TestClient(app)\\n    assert client.post(\\"/api/memory/synth\\", json={\\"days\\": 30, \\"identities\\": 20}).status_code == 401\\n    r = client.post(\\"/api/memory/synth\\", json={\\"days\\": 30, \\"identities\\": 20},\\n                    headers={\\"X-Analyst-Token\\": \\"t0k3n\\"})\\n    assert r.status_code == 200 and r.json()[\\"report\\"][\\"passed\\"] == 3\\n    assert client.get(\\"/api/memory/stats\\").json()[\\"rows\\"][\\"events\\"] > 0\\n    fs = client.get(\\"/api/memory/findings\\").json()[\\"findings\\"]\\n    assert fs\\n    v = client.get(f\\"/api/memory/identity/{fs[0][\'identity\']}\\").json()\\n    assert len(v[\\"days\\"]) == 30\\n    ev = client.get(\\"/api/memory/evidence\\", params={\\"ids\\": \\",\\".join(fs[0][\\"evidence\\"][:3])}).json()\\n    assert len(ev[\\"events\\"]) >= 1\\n    assert client.get(\\"/api/memory/identity/nobody\\").status_code == 404\\n    assert client.post(\\"/api/memory/ingest\\", json={\\"paths\\": [\\"/etc\\"]},\\n                       headers={\\"X-Analyst-Token\\": \\"t0k3n\\"}).status_code == 422\\n    assert client.post(\\"/api/memory/prune\\", json={}, headers={\\"X-Analyst-Token\\": \\"t0k3n\\"}).status_code == 200\\n"}')

MAIN_MARK = "app.memory30"
MAIN_LINES = ("from app.memory30 import api as _mem30_api  # 30-day memory kit\n"
              "app.include_router(_mem30_api.router, prefix=\"/api/memory\")\n")
GITIGNORE_LINES = ["data/memory30.sqlite*", "data/synth/"]


def ok(msg):
    print("[OK]   " + msg)


def warn(msg):
    print("[WARN] " + msg)


def fail(msg):
    print("[FAIL] " + msg)


def check(root):
    bad = 0
    for rel, content in FILES.items():
        p = root / rel
        if not p.exists():
            fail("missing " + rel); bad += 1
        elif p.read_text(encoding="utf-8") != content:
            warn("different from installer: " + rel); bad += 1
    main = root / "app" / "main.py"
    if main.exists() and MAIN_MARK in main.read_text(encoding="utf-8"):
        ok("app/main.py includes the /api/memory router")
    else:
        fail("app/main.py does not include the /api/memory router"); bad += 1
    print("ALL GOOD" if not bad else f"{bad} problem(s)")
    return 0 if not bad else 1


def patch_main(root):
    main = root / "app" / "main.py"
    if not main.exists():
        fail("app/main.py not found: add these two lines yourself before the static mount:\n" + MAIN_LINES)
        return False
    text = main.read_text(encoding="utf-8")
    if MAIN_MARK in text:
        ok("app/main.py already includes the memory router")
        return True
    lines = text.splitlines(keepends=True)
    idx = next((i for i, l in enumerate(lines) if l.lstrip().startswith("app.mount(")), None)
    if idx is None:
        lines.append("\n" + MAIN_LINES)
        warn("no app.mount(...) line found: router appended at the end of app/main.py "
             "(it must come BEFORE any static mount at '/')")
    else:
        lines.insert(idx, MAIN_LINES + "\n")
        ok(f"app/main.py: router added before line {idx + 1} (static mount)")
    main.write_text("".join(lines), encoding="utf-8")
    return True


def self_test(root):
    sys.path.insert(0, str(root))
    try:
        from app.memory30 import synth
        from app.memory30.engine import MemoryEngine
    except Exception as exc:  # noqa: BLE001
        fail(f"import failed: {exc.__class__.__name__}: {exc}")
        return False
    with tempfile.TemporaryDirectory() as tmp:
        eng = MemoryEngine(Path(tmp) / "selftest.sqlite")
        t0 = time.time()
        okta, ct, labels = synth.generate(days=30, identities=40, seed=42)
        res = eng.ingest_records(okta + ct)
        rep = synth.report(eng, labels)
        eng.close()
    secs = time.time() - t0
    msg = (f"self-test: {res['inserted']} events over 30 days, {rep['passed']}/{rep['total']} slow attacks found, "
           f"{rep['false_positive_count']} false positives, {secs:.1f}s")
    if rep["passed"] == rep["total"] and rep["false_positive_count"] == 0:
        ok(msg)
        return True
    fail(msg)
    return False


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    root = Path.cwd()
    if not (root / "app").is_dir():
        fail("run this from the project root (the folder that contains app/)")
        return 2
    if args.check:
        return check(root)
    stamp = time.strftime("%Y%m%d-%H%M%S")
    backup = root / ".mem30_backup" / stamp
    written = 0
    for rel, content in FILES.items():
        p = root / rel
        if p.exists() and p.read_text(encoding="utf-8") != content:
            (backup / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, backup / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding="utf-8")
        written += 1
    ok(f"{written} files written" + (f" (backups in {backup})" if backup.exists() else ""))
    for rel in FILES:
        if rel.endswith(".py"):
            try:
                py_compile.compile(str(root / rel), doraise=True)
            except py_compile.PyCompileError as exc:
                fail(f"compile error in {rel}: {exc}")
                return 1
    ok("all Python files compile")
    patch_main(root)
    gi = root / ".gitignore"
    existing = gi.read_text(encoding="utf-8").splitlines() if gi.exists() else []
    add = [l for l in GITIGNORE_LINES if l not in existing]
    if add:
        with gi.open("a", encoding="utf-8") as fh:
            fh.write(("\n" if existing and existing[-1] else "") + "\n".join(add) + "\n")
        ok(".gitignore updated")
    good = self_test(root)
    print()
    print("Next:")
    print("  python -m pytest -q tests/test_memory30.py")
    print("  python -m uvicorn app.main:app --port 8000   then open http://127.0.0.1:8000/memory.html")
    print("  click 'Generate 30-day test data'")
    return 0 if good else 1


if __name__ == "__main__":
    raise SystemExit(main())
